/// Active E2B lease window. Live handles refresh this TTL; auto-pause preserves
/// the runtime if the daemon hard-crashes, and explicit pause is the normal
/// Close/shutdown boundary.
const E2B_SESSION_TIMEOUT_SECS: u64 = 3600;

/// Runtime teardown is deliberately shorter than a lane command's normal
/// timeout. Discard must be able to break a review call that is waiting on the
/// very container being discarded, then acquire the workspace lease and remove
/// the clone only after every process owner is gone.
const ATTEMPT_ACTOR_STOP_TIMEOUT: Duration = Duration::from_secs(5);
// Podman on macOS proxies teardown through its VM. Keep this product-level
// deadline above the runtime's historical ten-second stop grace plus client/
// VM round-trip overhead; removal itself explicitly requests `--time 0`.
const ATTEMPT_CONTAINER_STOP_TIMEOUT: Duration = Duration::from_secs(30);
const ATTEMPT_OPERATION_RELEASE_TIMEOUT: Duration = Duration::from_secs(15);
/// Join a cancelled repository check and, if needed, its exact local runtime
/// cleanup before a lifecycle action acquires the Workspace operation.
const SESSION_DISPATCH_CLEANUP_TIMEOUT: Duration = Duration::from_secs(60);
/// Podman Desktop's macOS bind mount can briefly expose the old directory
/// entry after an atomic host rename. Ways keeps its nofollow host write, then
/// proves the replacement is consumable from the already-running container
/// before issuing the Git command that depends on it.
const ATTEMPT_GIT_BIND_VISIBILITY_TIMEOUT: Duration = Duration::from_secs(5);
const ATTEMPT_GIT_BIND_VISIBILITY_RETRY: Duration = Duration::from_millis(50);
const SESSION_TOOL_EVENT_VALUE_CAP: usize = 16 * 1024;
const SESSION_TOOL_EVENT_PREVIEW_CAP: usize = 8 * 1024;
const SESSION_CHECKPOINT_ADOPTION_ROOT: &str = "checkpoint-adoptions/session-turn-v1";
const SESSION_CHECKPOINT_ADOPTION_MARKER_MAX_BYTES: usize = 4 * 1024;
const PERSISTED_WORKFLOW_REFERENCE_MAX_BYTES: usize = 4 * 1024;
/// A Coordinator can register a Worker while its own stop is racing. Drain the
/// exact Session prefix repeatedly, but fail closed instead of allowing an
/// unbounded spawn/stop loop to hold admission forever.
const SESSION_ACTOR_DRAIN_ROUNDS: usize = 8;
const SESSION_SETUP_OUTPUT_CAP: usize = 16 * 1024;
const SESSION_SETUP_TIMEOUT: Duration = Duration::from_secs(900);
const SESSION_FILE_READ_CAP: u64 = 512 * 1024;
const SESSION_FILE_IO_TIMEOUT: Duration = Duration::from_secs(30);
const ATTEMPT_METADATA_JSON_CAP: usize = 32 * 1024 * 1024;
const PASSIVE_GIT_CONFIG_CAP: usize = 1024 * 1024;
const PASSIVE_GIT_EXCLUDE_CAP: usize = 1024 * 1024;
const PASSIVE_GIT_SCAN_DIRECT_ENTRY_CAP: usize = 100_000;
const PASSIVE_GIT_SCAN_TOTAL_ENTRY_CAP: usize = 2_000_000;
const PASSIVE_GIT_SCAN_DEPTH_CAP: usize = 64;
/// Review metadata is derived from Git but still crosses into daemon memory.
/// Bound both the passive path list and the streamed binary-patch identity.
const ATTEMPT_RAW_DIFF_CAP: usize = 32 * 1024 * 1024;
const ATTEMPT_PATCH_CAP: usize = 256 * 1024 * 1024;
const ATTEMPT_CHANGED_PATH_CAP: usize = 50_000;
/// Keep currently materializes one retained leaf at a time so it can bind raw
/// bytes to the protected Git blob and make a resumable same-filesystem copy.
/// A per-leaf ceiling prevents sparse/large files from becoming allocations;
/// the combined preimage + postimage ceiling also bounds one durable journal.
const KEEP_LEAF_CAP: usize = 64 * 1024 * 1024;
const KEEP_TRANSACTION_PAYLOAD_CAP: u64 = 512 * 1024 * 1024;
/// The registry wraps the MCP gate, so its deadline must leave the gate enough
/// time to produce its own safe deny and resolution frame.
const MCP_APPROVAL_HOOK_TIMEOUT: Duration =
    axocoatl_mcp::approval::MCP_APPROVAL_TIMEOUT.saturating_add(Duration::from_secs(30));

