    struct FallbackRouteProbe {
        id: &'static str,
        model: &'static str,
        rate_limited: bool,
        calls: Arc<std::sync::atomic::AtomicUsize>,
        model_overrides: Arc<StdMutex<Vec<Option<String>>>>,
    }

    #[async_trait::async_trait]
    impl axocoatl_llm::LlmProvider for FallbackRouteProbe {
        fn provider_id(&self) -> &str {
            self.id
        }

        fn model_id(&self) -> &str {
            self.model
        }

        fn capabilities(&self) -> axocoatl_llm::ProviderCapabilities {
            axocoatl_llm::ProviderCapabilities {
                tool_calling: true,
                ..Default::default()
            }
        }

        async fn chat(
            &self,
            request: axocoatl_llm::ChatRequest,
        ) -> Result<axocoatl_llm::ChatResponse, axocoatl_llm::ProviderError> {
            let call = self.calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            self.model_overrides
                .lock()
                .unwrap()
                .push(request.model_override.clone());
            if self.rate_limited {
                return Err(axocoatl_llm::ProviderError::RateLimited {
                    provider: self.id.to_string(),
                    retry_after_secs: Some(1),
                });
            }
            if call == 0 {
                Ok(axocoatl_llm::ChatResponse {
                    content: String::new(),
                    tool_calls: vec![axocoatl_llm::ToolCall {
                        id: "fallback-call".to_string(),
                        name: "read_file".to_string(),
                        arguments: serde_json::json!({"path":"src/lib.rs"}),
                        provider_metadata: Default::default(),
                    }],
                    finish_reason: axocoatl_llm::FinishReason::ToolUse,
                    usage: axocoatl_core::TokenUsageStats::new(10, 3),
                    model: request
                        .model_override
                        .clone()
                        .unwrap_or_else(|| self.model.to_string()),
                    provider: self.id.to_string(),
                })
            } else {
                Ok(axocoatl_llm::ChatResponse {
                    content: "fallback route stayed pinned".to_string(),
                    tool_calls: Vec::new(),
                    finish_reason: axocoatl_llm::FinishReason::Stop,
                    usage: axocoatl_core::TokenUsageStats::new(10, 4),
                    model: request
                        .model_override
                        .clone()
                        .unwrap_or_else(|| self.model.to_string()),
                    provider: self.id.to_string(),
                })
            }
        }

        async fn chat_stream(
            &self,
            _request: axocoatl_llm::ChatRequest,
        ) -> Result<
            std::pin::Pin<
                Box<
                    dyn tokio_stream::Stream<
                            Item = Result<axocoatl_llm::StreamEvent, axocoatl_llm::ProviderError>,
                        > + Send,
                >,
            >,
            axocoatl_llm::ProviderError,
        > {
            Err(axocoatl_llm::ProviderError::Stream(
                "fallback probe uses non-streaming calls".to_string(),
            ))
        }
    }

    struct SessionHookProbeLlm {
        calls: std::sync::atomic::AtomicUsize,
    }

    #[derive(Default)]
    struct CoordinatedPartialFailureBehavior {
        sink: Option<axocoatl_actor::StreamSink>,
    }

    struct GenericExecutionProbeBehavior {
        dispatches: Arc<std::sync::atomic::AtomicUsize>,
    }

    #[async_trait::async_trait]
    impl axocoatl_actor::AgentBehavior for GenericExecutionProbeBehavior {
        async fn on_start(
            &mut self,
            _config: &axocoatl_core::AgentConfig,
        ) -> Result<(), axocoatl_actor::AgentError> {
            Ok(())
        }

        async fn execute(
            &mut self,
            _input: axocoatl_core::AgentInput,
        ) -> Result<axocoatl_core::AgentOutput, axocoatl_actor::AgentError> {
            self.dispatches
                .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Ok(axocoatl_core::AgentOutput::text("top-level executed"))
        }

        async fn on_stop(&mut self) -> Result<(), axocoatl_actor::AgentError> {
            Ok(())
        }
    }

    #[async_trait::async_trait]
    impl axocoatl_actor::AgentBehavior for CoordinatedPartialFailureBehavior {
        async fn on_start(
            &mut self,
            _config: &axocoatl_core::AgentConfig,
        ) -> Result<(), axocoatl_actor::AgentError> {
            Ok(())
        }

        async fn execute(
            &mut self,
            _input: axocoatl_core::AgentInput,
        ) -> Result<axocoatl_core::AgentOutput, axocoatl_actor::AgentError> {
            if let Some(sink) = &self.sink {
                let _ = sink.send(axocoatl_actor::AgentStreamChunk::Text(
                    "partial 🦎 evidence".to_string(),
                ));
            }
            Err(axocoatl_actor::AgentError::Internal(
                "provider failed after text".to_string(),
            ))
        }

        fn set_stream_sink(&mut self, sink: Option<axocoatl_actor::StreamSink>) {
            self.sink = sink;
        }

        fn last_execution_token_usage_measurement(
            &self,
        ) -> Option<axocoatl_core::MeasuredTokenUsage> {
            Some(axocoatl_core::MeasuredTokenUsage::known(
                axocoatl_core::TokenUsageStats::new(7, 3),
            ))
        }

        async fn on_stop(&mut self) -> Result<(), axocoatl_actor::AgentError> {
            Ok(())
        }
    }

    #[tokio::test]
    async fn generic_agent_execute_uses_config_authority_before_registry_membership() {
        let config = test_config();
        let registry = AgentRegistry::new();
        let top_level_id = AgentId::new("test-agent");
        let scoped_id = AgentId::new("session-a:test-agent");
        let top_level_dispatches = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let scoped_dispatches = Arc::new(std::sync::atomic::AtomicUsize::new(0));

        let (top_level, top_level_handle) = AgentActor::spawn(
            Some(format!("generic-top-level-{}", uuid::Uuid::new_v4())),
            AgentActor,
            (
                axocoatl_core::AgentConfig {
                    id: top_level_id.clone(),
                    ..Default::default()
                },
                Box::new(GenericExecutionProbeBehavior {
                    dispatches: top_level_dispatches.clone(),
                }) as Box<dyn axocoatl_actor::AgentBehavior>,
            ),
        )
        .await
        .unwrap();
        let (scoped, scoped_handle) = AgentActor::spawn(
            Some(format!("generic-scoped-{}", uuid::Uuid::new_v4())),
            AgentActor,
            (
                axocoatl_core::AgentConfig {
                    id: scoped_id.clone(),
                    ..Default::default()
                },
                Box::new(GenericExecutionProbeBehavior {
                    dispatches: scoped_dispatches.clone(),
                }) as Box<dyn axocoatl_actor::AgentBehavior>,
            ),
        )
        .await
        .unwrap();
        registry
            .register(top_level_id.clone(), top_level.clone())
            .await;
        registry.register(scoped_id.clone(), scoped.clone()).await;

        let rejected = execute_configured_agent_input_measured(
            &config,
            &registry,
            "session-a:test-agent",
            axocoatl_core::AgentInput::text("must not dispatch"),
        )
        .await
        .unwrap_err();
        assert!(rejected
            .to_string()
            .contains("not a configured top-level Agent"));
        assert_eq!(rejected.token_usage.total(), 0);
        assert!(rejected.token_usage_known);
        assert_eq!(scoped_dispatches.load(Ordering::SeqCst), 0);

        let allowed = execute_configured_agent_input_measured(
            &config,
            &registry,
            "test-agent",
            axocoatl_core::AgentInput::text("run"),
        )
        .await
        .unwrap();
        assert_eq!(allowed.output.content, "top-level executed");
        assert_eq!(top_level_dispatches.load(Ordering::SeqCst), 1);

        let worker = require_configured_executable_agent(&role_test_config(), "worker")
            .unwrap_err()
            .to_string();
        assert!(worker.contains("coordinator-owned worker"));

        top_level.stop(None);
        scoped.stop(None);
        top_level_handle.await.unwrap();
        scoped_handle.await.unwrap();
    }

    #[tokio::test]
    async fn settings_live_update_preserves_active_turn_then_retires_only_exact_idle_actor() {
        let registry = AgentRegistry::new();
        let session_id = format!("settings-session-{}", uuid::Uuid::new_v4());
        let agent_id = "test-agent";
        let exact_id = AgentId::new(format!("{session_id}:{agent_id}"));
        let worker_id = AgentId::new(format!("{session_id}:{agent_id}:worker:reviewer"));

        let (exact, exact_handle) = AgentActor::spawn(
            Some(exact_id.to_string()),
            AgentActor,
            (
                axocoatl_core::AgentConfig {
                    id: exact_id.clone(),
                    ..Default::default()
                },
                Box::new(GenericExecutionProbeBehavior {
                    dispatches: Arc::new(std::sync::atomic::AtomicUsize::new(0)),
                }) as Box<dyn axocoatl_actor::AgentBehavior>,
            ),
        )
        .await
        .unwrap();
        let (worker, worker_handle) = AgentActor::spawn(
            Some(worker_id.to_string()),
            AgentActor,
            (
                axocoatl_core::AgentConfig {
                    id: worker_id.clone(),
                    ..Default::default()
                },
                Box::new(GenericExecutionProbeBehavior {
                    dispatches: Arc::new(std::sync::atomic::AtomicUsize::new(0)),
                }) as Box<dyn axocoatl_actor::AgentBehavior>,
            ),
        )
        .await
        .unwrap();
        registry.register(exact_id.clone(), exact).await;
        registry.register(worker_id.clone(), worker.clone()).await;

        let active = tokio::sync::Mutex::new(HashMap::from([(
            session_id.clone(),
            ActiveSessionTurn {
                turn_id: "turn-active".to_string(),
                control: AgentRunControl::new(AgentRunId::new("turn-active")),
            },
        )]));
        let sessions = vec![session_id.clone()];
        let rejected = AxocoatlDaemon::retire_idle_session_agent_instances(
            &registry, &active, &sessions, agent_id,
        )
        .await
        .unwrap_err();
        assert!(matches!(rejected, DaemonError::SessionConflict(_)));
        assert!(registry.get(&exact_id).await.is_some());
        assert!(registry.get(&worker_id).await.is_some());

        active.lock().await.clear();
        AxocoatlDaemon::retire_idle_session_agent_instances(
            &registry, &active, &sessions, agent_id,
        )
        .await
        .unwrap();
        assert!(registry.get(&exact_id).await.is_none());
        assert!(
            registry.get(&worker_id).await.is_some(),
            "a template update must not seize a Coordinator Worker's lifecycle"
        );
        exact_handle.await.unwrap();

        // The next Session turn can now create the same canonical scoped name
        // and therefore cannot reuse the actor built from stale config.
        let (replacement, replacement_handle) = AgentActor::spawn(
            Some(exact_id.to_string()),
            AgentActor,
            (
                axocoatl_core::AgentConfig {
                    id: exact_id.clone(),
                    ..Default::default()
                },
                Box::new(GenericExecutionProbeBehavior {
                    dispatches: Arc::new(std::sync::atomic::AtomicUsize::new(0)),
                }) as Box<dyn axocoatl_actor::AgentBehavior>,
            ),
        )
        .await
        .expect("retired exact Session identity should be available for the next turn");
        registry
            .register(exact_id.clone(), replacement.clone())
            .await;
        assert!(registry.get(&exact_id).await.is_some());

        replacement.stop(None);
        worker.stop(None);
        replacement_handle.await.unwrap();
        worker_handle.await.unwrap();
    }

    #[tokio::test]
    async fn legacy_chat_actor_resolution_reauthorizes_persisted_agent_id() {
        let config = test_config();
        let registry = AgentRegistry::new();
        let scoped_id = AgentId::new("session-owned:test-agent");
        let dispatches = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let (scoped, handle) = AgentActor::spawn(
            Some(format!("chat-authority-{}", uuid::Uuid::new_v4())),
            AgentActor,
            (
                axocoatl_core::AgentConfig {
                    id: scoped_id.clone(),
                    ..Default::default()
                },
                Box::new(GenericExecutionProbeBehavior {
                    dispatches: dispatches.clone(),
                }) as Box<dyn axocoatl_actor::AgentBehavior>,
            ),
        )
        .await
        .unwrap();
        registry.register(scoped_id.clone(), scoped.clone()).await;

        let error =
            configured_agent_actor_from_registry(&config, &registry, "session-owned:test-agent")
                .await
                .unwrap_err();
        assert!(error
            .to_string()
            .contains("not a configured top-level Agent"));
        assert_eq!(dispatches.load(Ordering::SeqCst), 0);
        assert!(
            registry.get(&scoped_id).await.is_some(),
            "rejected Chat authority must not mutate the Session actor"
        );

        scoped.stop(None);
        handle.await.unwrap();
    }

    #[tokio::test]
    async fn failed_actor_stop_retains_ownership_until_a_successful_retry() {
        assert!(terminal_requires_fresh_session_actor(
            SessionTurnLifecycle::Failed
        ));
        assert!(terminal_requires_fresh_session_actor(
            SessionTurnLifecycle::Cancelled
        ));
        assert!(terminal_requires_fresh_session_actor(
            SessionTurnLifecycle::Interrupted
        ));
        assert!(!terminal_requires_fresh_session_actor(
            SessionTurnLifecycle::Completed
        ));
        let registry = AgentRegistry::new();
        let blocked_id = AgentId::new("session-stop:lead");
        let stopped_id = AgentId::new("session-stop:lead:worker:tester");
        let late_id = AgentId::new("session-stop:lead:worker:late");
        let (blocked_actor, blocked_handle) = AgentActor::spawn(
            Some("session-stop-blocked".to_string()),
            AgentActor,
            (
                axocoatl_core::AgentConfig {
                    id: blocked_id.clone(),
                    ..Default::default()
                },
                Box::new(CoordinatedPartialFailureBehavior::default())
                    as Box<dyn axocoatl_actor::AgentBehavior>,
            ),
        )
        .await
        .unwrap();
        let (stopped_actor, stopped_handle) = AgentActor::spawn(
            Some("session-stop-confirmed".to_string()),
            AgentActor,
            (
                axocoatl_core::AgentConfig {
                    id: stopped_id.clone(),
                    ..Default::default()
                },
                Box::new(CoordinatedPartialFailureBehavior::default())
                    as Box<dyn axocoatl_actor::AgentBehavior>,
            ),
        )
        .await
        .unwrap();
        let (late_actor, late_handle) = AgentActor::spawn(
            Some("session-stop-late-worker".to_string()),
            AgentActor,
            (
                axocoatl_core::AgentConfig {
                    id: late_id.clone(),
                    ..Default::default()
                },
                Box::new(CoordinatedPartialFailureBehavior::default())
                    as Box<dyn axocoatl_actor::AgentBehavior>,
            ),
        )
        .await
        .unwrap();
        let orphan_name = "session-stop:lead:worker:orphan#1";
        let (orphan_actor, orphan_handle) = AgentActor::spawn(
            Some(orphan_name.to_string()),
            AgentActor,
            (
                axocoatl_core::AgentConfig {
                    id: AgentId::new(orphan_name),
                    ..Default::default()
                },
                Box::new(CoordinatedPartialFailureBehavior::default())
                    as Box<dyn axocoatl_actor::AgentBehavior>,
            ),
        )
        .await
        .unwrap();
        registry
            .register(blocked_id.clone(), blocked_actor.clone())
            .await;
        registry
            .register(stopped_id.clone(), stopped_actor.clone())
            .await;

        let fail_blocked = Arc::new(AtomicBool::new(true));
        let provider_or_tool_dispatches = std::sync::atomic::AtomicUsize::new(0);
        let injected = fail_blocked.clone();
        let boundary = AxocoatlDaemon::stop_session_actor_instances_with(
            &registry,
            "session-stop",
            move |actor_id, actor| {
                let injected = injected.clone();
                async move {
                    if actor_id == AgentId::new("session-stop:lead")
                        && injected.load(Ordering::SeqCst)
                    {
                        Err("injected stop timeout".to_string())
                    } else {
                        actor
                            .stop_and_wait(None, Some(Duration::from_secs(1)))
                            .await
                            .map_err(|error| error.to_string())
                    }
                }
            },
        )
        .await;
        if boundary.is_ok() {
            provider_or_tool_dispatches.fetch_add(1, Ordering::SeqCst);
        }
        let error = boundary.unwrap_err().to_string();
        assert!(error.contains("injected stop timeout"));
        assert_eq!(provider_or_tool_dispatches.load(Ordering::SeqCst), 0);
        assert!(
            registry.get(&blocked_id).await.is_some(),
            "an unconfirmed executor remains the next-turn ownership guard"
        );
        assert!(registry.get(&stopped_id).await.is_none());
        assert!(ractor::registry::where_is(orphan_name.to_string()).is_none());

        fail_blocked.store(false, Ordering::SeqCst);
        let injected = fail_blocked.clone();
        let late_registered = Arc::new(AtomicBool::new(false));
        let registered = late_registered.clone();
        let registry_for_late_worker = registry.clone();
        let late_id_for_registration = late_id.clone();
        let late_actor_for_registration = late_actor.clone();
        let boundary = AxocoatlDaemon::stop_session_actor_instances_with(
            &registry,
            "session-stop",
            move |actor_id, actor| {
                let injected = injected.clone();
                let registered = registered.clone();
                let registry = registry_for_late_worker.clone();
                let late_id = late_id_for_registration.clone();
                let late_actor = late_actor_for_registration.clone();
                async move {
                    if actor_id == AgentId::new("session-stop:lead")
                        && injected.load(Ordering::SeqCst)
                    {
                        Err("injected stop timeout".to_string())
                    } else {
                        if actor_id == AgentId::new("session-stop:lead")
                            && !registered.swap(true, Ordering::SeqCst)
                        {
                            // Simulate a Coordinator registering a Worker while
                            // the first shutdown snapshot is already draining.
                            registry.register(late_id, late_actor).await;
                        }
                        actor
                            .stop_and_wait(None, Some(Duration::from_secs(1)))
                            .await
                            .map_err(|error| error.to_string())
                    }
                }
            },
        )
        .await;
        if boundary.is_ok() {
            provider_or_tool_dispatches.fetch_add(1, Ordering::SeqCst);
        }
        boundary.unwrap();
        assert!(registry.get(&blocked_id).await.is_none());
        assert!(late_registered.load(Ordering::SeqCst));
        assert!(registry.get(&late_id).await.is_none());
        assert_eq!(provider_or_tool_dispatches.load(Ordering::SeqCst), 1);

        blocked_actor.stop(None);
        stopped_actor.stop(None);
        late_actor.stop(None);
        orphan_actor.stop(None);
        blocked_handle.await.unwrap();
        stopped_handle.await.unwrap();
        late_handle.await.unwrap();
        orphan_handle.await.unwrap();
    }

    #[tokio::test]
    async fn failed_and_cancelled_exact_retries_settle_retained_actor_before_cached_outcome() {
        use ractor::Actor;

        for (label, status) in [
            ("cancelled", SessionTurnLifecycle::Cancelled),
            ("failed", SessionTurnLifecycle::Failed),
        ] {
            let session_id = format!("terminal-retry-{label}");
            let actor_id = AgentId::new(format!("{session_id}:coder"));
            let registry = AgentRegistry::new();
            let (actor, handle) = AgentActor::spawn(
                Some(format!("{session_id}:coder")),
                AgentActor,
                (
                    axocoatl_core::AgentConfig {
                        id: actor_id.clone(),
                        ..Default::default()
                    },
                    Box::new(CoordinatedPartialFailureBehavior::default())
                        as Box<dyn axocoatl_actor::AgentBehavior>,
                ),
            )
            .await
            .unwrap();
            registry.register(actor_id.clone(), actor).await;

            let mut turn = projection_turn();
            turn.id = format!("turn-{label}");
            turn.session_id = session_id.clone();
            turn.status = status;
            turn.final_output = None;
            turn.error =
                (status == SessionTurnLifecycle::Failed).then(|| "provider failed".to_string());

            let dispatches = std::sync::atomic::AtomicUsize::new(0);
            let first_boundary = if terminal_requires_fresh_session_actor(turn.status) {
                AxocoatlDaemon::stop_session_actor_instances_with(
                    &registry,
                    &session_id,
                    |_, _| async { Err("injected first stop failure".to_string()) },
                )
                .await
            } else {
                Ok(())
            };
            let first = first_boundary.and_then(|()| {
                dispatches.fetch_add(1, Ordering::SeqCst);
                AxocoatlDaemon::outcome_from_terminal_turn(turn.clone())
            });
            let error = first.unwrap_err().to_string();
            assert!(error.contains("injected first stop failure"), "{error}");
            assert_eq!(dispatches.load(Ordering::SeqCst), 0);
            assert!(registry.get(&actor_id).await.is_some());

            AxocoatlDaemon::stop_session_actor_instances_with(
                &registry,
                &session_id,
                |_, actor| async move {
                    actor
                        .stop_and_wait(None, Some(Duration::from_secs(1)))
                        .await
                        .map_err(|error| error.to_string())
                },
            )
            .await
            .unwrap();
            let retry = AxocoatlDaemon::outcome_from_terminal_turn(turn);
            dispatches.fetch_add(1, Ordering::SeqCst);
            assert!(registry.get(&actor_id).await.is_none());
            assert_eq!(dispatches.load(Ordering::SeqCst), 1);
            match status {
                SessionTurnLifecycle::Cancelled => {
                    assert!(retry.unwrap().is_cancelled());
                }
                SessionTurnLifecycle::Failed => {
                    assert!(retry.unwrap_err().to_string().contains("provider failed"));
                }
                _ => unreachable!(),
            }
            handle.await.unwrap();
        }
    }

    #[async_trait::async_trait]
    impl axocoatl_llm::LlmProvider for SessionHookProbeLlm {
        fn provider_id(&self) -> &str {
            "session-hook-probe"
        }

        fn model_id(&self) -> &str {
            "session-hook-probe"
        }

        fn capabilities(&self) -> axocoatl_llm::ProviderCapabilities {
            axocoatl_llm::ProviderCapabilities {
                tool_calling: true,
                ..Default::default()
            }
        }

        async fn chat(
            &self,
            _request: axocoatl_llm::ChatRequest,
        ) -> Result<axocoatl_llm::ChatResponse, axocoatl_llm::ProviderError> {
            let call = self.calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            if call == 0 {
                Ok(axocoatl_llm::ChatResponse {
                    content: String::new(),
                    tool_calls: vec![axocoatl_llm::ToolCall {
                        id: "call-side-effect".to_string(),
                        name: "external_side_effect".to_string(),
                        arguments: serde_json::json!({"value":"must not run"}),
                        provider_metadata: Default::default(),
                    }],
                    finish_reason: axocoatl_llm::FinishReason::ToolUse,
                    usage: axocoatl_core::TokenUsageStats::new(10, 1),
                    model: self.model_id().to_string(),
                    provider: self.provider_id().to_string(),
                })
            } else {
                Ok(axocoatl_llm::ChatResponse {
                    content: "The external tool was denied and did not run.".to_string(),
                    tool_calls: Vec::new(),
                    finish_reason: axocoatl_llm::FinishReason::Stop,
                    usage: axocoatl_core::TokenUsageStats::new(10, 8),
                    model: self.model_id().to_string(),
                    provider: self.provider_id().to_string(),
                })
            }
        }

        async fn chat_stream(
            &self,
            _request: axocoatl_llm::ChatRequest,
        ) -> Result<
            std::pin::Pin<
                Box<
                    dyn tokio_stream::Stream<
                            Item = Result<axocoatl_llm::StreamEvent, axocoatl_llm::ProviderError>,
                        > + Send,
                >,
            >,
            axocoatl_llm::ProviderError,
        > {
            let call = self.calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            let events = if call == 0 {
                vec![
                    Ok(axocoatl_llm::StreamEvent::ToolCallDelta {
                        index: Some(0),
                        id: "call-side-effect".to_string(),
                        name: Some("external_side_effect".to_string()),
                        args_delta: r#"{"value":"must not run"}"#.to_string(),
                    }),
                    Ok(axocoatl_llm::StreamEvent::Usage(
                        axocoatl_core::TokenUsageStats::new(10, 1),
                    )),
                    Ok(axocoatl_llm::StreamEvent::Done {
                        finish_reason: axocoatl_llm::FinishReason::ToolUse,
                    }),
                ]
            } else {
                vec![
                    Ok(axocoatl_llm::StreamEvent::TextDelta {
                        delta: "The external tool was denied and did not run.".to_string(),
                    }),
                    Ok(axocoatl_llm::StreamEvent::Usage(
                        axocoatl_core::TokenUsageStats::new(10, 8),
                    )),
                    Ok(axocoatl_llm::StreamEvent::Done {
                        finish_reason: axocoatl_llm::FinishReason::Stop,
                    }),
                ]
            };
            Ok(Box::pin(tokio_stream::iter(events)))
        }
    }

    struct SessionHookSideEffect {
        executions: Arc<std::sync::atomic::AtomicUsize>,
    }

    #[async_trait::async_trait]
    impl axocoatl_tools::BuiltinTool for SessionHookSideEffect {
        fn description(&self) -> &str {
            "A side-effect probe that must stay behind Session hooks"
        }

        fn parameters_schema(&self) -> serde_json::Value {
            serde_json::json!({"type":"object"})
        }

        async fn execute(
            &self,
            _arguments: serde_json::Value,
        ) -> Result<serde_json::Value, axocoatl_tools::ToolError> {
            self.executions
                .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Ok(serde_json::json!({"ran":true}))
        }
    }

    struct CancelledRestartProbeLlm {
        captured: Arc<StdMutex<Vec<Vec<axocoatl_core::ChatMessage>>>>,
        stale_calls: std::sync::atomic::AtomicUsize,
    }

    impl CancelledRestartProbeLlm {
        fn request_excludes_cancelled_plan(messages: &[axocoatl_core::ChatMessage]) -> bool {
            const NEXT: &str = "Reply with exactly: NEXT TURN OK. Do not call any tools.";
            let Some(next_user) = messages.iter().rposition(|message| {
                message.role == axocoatl_core::MessageRole::User
                    && message.text_content() == Some(NEXT)
            }) else {
                return false;
            };
            next_user + 1 == messages.len()
                && messages.iter().all(|message| {
                    !message
                        .text_content()
                        .is_some_and(|content| content.contains("OLD PLAN"))
                        && message
                            .tool_calls
                            .iter()
                            .all(|call| call.name != "edit_file")
                        && message.tool_call_id.as_deref() != Some("call-old-edit")
                })
        }

        fn record_and_is_clean(&self, request: axocoatl_llm::ChatRequest) -> bool {
            let clean = Self::request_excludes_cancelled_plan(&request.messages);
            self.captured.lock().unwrap().push(request.messages);
            clean
        }
    }

    #[async_trait::async_trait]
    impl axocoatl_llm::LlmProvider for CancelledRestartProbeLlm {
        fn provider_id(&self) -> &str {
            "cancelled-restart-probe"
        }

        fn model_id(&self) -> &str {
            "cancelled-restart-probe"
        }

        fn capabilities(&self) -> axocoatl_llm::ProviderCapabilities {
            axocoatl_llm::ProviderCapabilities {
                streaming: true,
                tool_calling: true,
                ..Default::default()
            }
        }

        async fn chat(
            &self,
            request: axocoatl_llm::ChatRequest,
        ) -> Result<axocoatl_llm::ChatResponse, axocoatl_llm::ProviderError> {
            let clean = self.record_and_is_clean(request);
            let stale = self
                .stale_calls
                .fetch_add((!clean) as usize, std::sync::atomic::Ordering::SeqCst);
            Ok(axocoatl_llm::ChatResponse {
                content: if clean {
                    "NEXT TURN OK".to_string()
                } else if stale == 0 {
                    String::new()
                } else {
                    "STALE PLAN CONTINUED".to_string()
                },
                tool_calls: if !clean && stale == 0 {
                    vec![axocoatl_llm::ToolCall {
                        id: "call-stale-edit".to_string(),
                        name: "edit_file".to_string(),
                        arguments: serde_json::json!({"path":"lib/catalog.js"}),
                        provider_metadata: Default::default(),
                    }]
                } else {
                    Vec::new()
                },
                finish_reason: if !clean && stale == 0 {
                    axocoatl_llm::FinishReason::ToolUse
                } else {
                    axocoatl_llm::FinishReason::Stop
                },
                usage: axocoatl_core::TokenUsageStats::new(20, 3),
                model: self.model_id().to_string(),
                provider: self.provider_id().to_string(),
            })
        }

        async fn chat_stream(
            &self,
            request: axocoatl_llm::ChatRequest,
        ) -> Result<
            std::pin::Pin<
                Box<
                    dyn tokio_stream::Stream<
                            Item = Result<axocoatl_llm::StreamEvent, axocoatl_llm::ProviderError>,
                        > + Send,
                >,
            >,
            axocoatl_llm::ProviderError,
        > {
            let clean = self.record_and_is_clean(request);
            let stale = self
                .stale_calls
                .fetch_add((!clean) as usize, std::sync::atomic::Ordering::SeqCst);
            let mut events = Vec::new();
            if clean {
                events.push(Ok(axocoatl_llm::StreamEvent::TextDelta {
                    delta: "NEXT TURN OK".to_string(),
                }));
            } else if stale == 0 {
                events.push(Ok(axocoatl_llm::StreamEvent::ToolCallDelta {
                    index: Some(0),
                    id: "call-stale-edit".to_string(),
                    name: Some("edit_file".to_string()),
                    args_delta: r#"{"path":"lib/catalog.js"}"#.to_string(),
                }));
            } else {
                events.push(Ok(axocoatl_llm::StreamEvent::TextDelta {
                    delta: "STALE PLAN CONTINUED".to_string(),
                }));
            }
            events.push(Ok(axocoatl_llm::StreamEvent::Usage(
                axocoatl_core::TokenUsageStats::new(20, 3),
            )));
            events.push(Ok(axocoatl_llm::StreamEvent::Done {
                finish_reason: if !clean && stale == 0 {
                    axocoatl_llm::FinishReason::ToolUse
                } else {
                    axocoatl_llm::FinishReason::Stop
                },
            }));
            Ok(Box::pin(tokio_stream::iter(events)))
        }
    }

    #[derive(Clone, Copy)]
    enum InjectedGitCommandFailure {
        Nonzero,
        ExecError,
    }

    #[derive(Clone)]
    struct GitBoundaryFinalizerProbe {
        trigger: &'static str,
        failure: InjectedGitCommandFailure,
        triggered: Arc<std::sync::atomic::AtomicBool>,
    }

    #[derive(Clone)]
    struct LocalGitSandbox {
        root: std::path::PathBuf,
        commands: Arc<StdMutex<Vec<Vec<String>>>>,
        finalizer_probe: Option<GitBoundaryFinalizerProbe>,
        transient_git_failures: Option<Arc<std::sync::atomic::AtomicUsize>>,
    }

    impl LocalGitSandbox {
        fn new(root: &std::path::Path) -> Self {
            Self {
                root: root.to_path_buf(),
                commands: Arc::new(StdMutex::new(Vec::new())),
                finalizer_probe: None,
                transient_git_failures: None,
            }
        }

        fn with_transient_git_failures(mut self, count: usize) -> Self {
            self.transient_git_failures =
                Some(Arc::new(std::sync::atomic::AtomicUsize::new(count)));
            self
        }

        fn with_boundary_finalizer_probe(
            mut self,
            trigger: &'static str,
            failure: InjectedGitCommandFailure,
        ) -> Self {
            self.finalizer_probe = Some(GitBoundaryFinalizerProbe {
                trigger,
                failure,
                triggered: Arc::new(std::sync::atomic::AtomicBool::new(false)),
            });
            self
        }

        fn commands(&self) -> Vec<Vec<String>> {
            self.commands.lock().unwrap().clone()
        }

        fn run(
            &self,
            argv: &[&str],
            stdin: Option<&str>,
        ) -> Result<ExecResult, axocoatl_isolation::IsolationError> {
            use std::io::Write as _;

            self.commands.lock().unwrap().push(
                argv.iter()
                    .map(|argument| (*argument).to_string())
                    .collect(),
            );
            let transient_failure = self
                .transient_git_failures
                .as_ref()
                .is_some_and(|remaining| {
                    remaining
                        .fetch_update(
                            std::sync::atomic::Ordering::SeqCst,
                            std::sync::atomic::Ordering::SeqCst,
                            |count| {
                                if count > 0 {
                                    Some(count - 1)
                                } else {
                                    None
                                }
                            },
                        )
                        .is_ok()
                });
            if transient_failure {
                return Ok(ExecResult {
                    stdout: String::new(),
                    stderr: "fatal: cannot use .git/info/exclude as an exclude file".to_string(),
                    exit_code: 128,
                });
            }
            let mut command = std::process::Command::new(argv.first().copied().unwrap_or("false"));
            command.args(&argv[1..]).current_dir(&self.root);
            if stdin.is_some() {
                command.stdin(std::process::Stdio::piped());
            }
            command.stdout(std::process::Stdio::piped());
            command.stderr(std::process::Stdio::piped());
            let mut child = command.spawn()?;
            if let Some(stdin) = stdin {
                child
                    .stdin
                    .take()
                    .ok_or_else(|| {
                        axocoatl_isolation::IsolationError::OciContainerFailed(
                            "local test command did not expose stdin".to_string(),
                        )
                    })?
                    .write_all(stdin.as_bytes())?;
            }
            let output = child.wait_with_output()?;
            let result = ExecResult {
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
                exit_code: output.status.code().unwrap_or(-1),
            };
            let inject = self.finalizer_probe.as_ref().is_some_and(|probe| {
                argv.contains(&probe.trigger)
                    && !probe
                        .triggered
                        .swap(true, std::sync::atomic::Ordering::SeqCst)
            });
            if inject {
                let probe = self.finalizer_probe.as_ref().unwrap();
                let refs = self.root.join(".git/refs");
                let retained = self.root.join(".git/refs-before-finalizer-probe");
                std::fs::rename(&refs, &retained)?;
                std::fs::create_dir(&refs)?;
                return match probe.failure {
                    InjectedGitCommandFailure::Nonzero => Ok(ExecResult {
                        stdout: String::new(),
                        stderr: "injected nonzero Git result".to_string(),
                        exit_code: 1,
                    }),
                    InjectedGitCommandFailure::ExecError => {
                        Err(axocoatl_isolation::IsolationError::OciContainerFailed(
                            "injected Git execution error".to_string(),
                        ))
                    }
                };
            }
            Ok(result)
        }
    }

    #[async_trait::async_trait]
    impl Sandbox for LocalGitSandbox {
        fn root(&self) -> &std::path::Path {
            &self.root
        }

        async fn exec(
            &self,
            argv: &[&str],
            _timeout: Duration,
        ) -> Result<ExecResult, axocoatl_isolation::IsolationError> {
            self.run(argv, None)
        }

        async fn exec_stdin(
            &self,
            argv: &[&str],
            stdin: &str,
            _timeout: Duration,
        ) -> Result<ExecResult, axocoatl_isolation::IsolationError> {
            self.run(argv, Some(stdin))
        }

        fn spawn_background(&self, _command: &str) -> String {
            panic!("background processes are not used by the local Git test sandbox")
        }

        fn spawn_pty(
            &self,
            _command: &str,
            _rows: u16,
            _cols: u16,
        ) -> Result<Arc<axocoatl_isolation::pty::PtyTerminal>, String> {
            Err("PTYs are not used by the local Git test sandbox".to_string())
        }

        fn get_terminal(&self, _id: &str) -> Option<Arc<axocoatl_isolation::pty::PtyTerminal>> {
            None
        }

        fn kill_terminal(&self, _id: &str) -> bool {
            false
        }

        fn list_terminals(&self) -> Vec<(String, String, bool)> {
            Vec::new()
        }

        fn list_tasks(&self) -> Vec<axocoatl_isolation::session_sandbox::BgTask> {
            Vec::new()
        }

        fn with_root(&self, root: &std::path::Path) -> Arc<dyn Sandbox> {
            Arc::new(Self {
                root: root.to_path_buf(),
                commands: self.commands.clone(),
                finalizer_probe: self.finalizer_probe.clone(),
                transient_git_failures: self.transient_git_failures.clone(),
            })
        }

        async fn stop(&self) {}
    }

    fn run_test_git(root: &std::path::Path, args: &[&str]) -> String {
        let output = std::process::Command::new("git")
            .arg("-C")
            .arg(root)
            .args(args)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "git {args:?}: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        String::from_utf8_lossy(&output.stdout).trim().to_string()
    }

    fn init_test_git_repository(root: &std::path::Path, sha256: bool) -> String {
        if sha256 {
            run_test_git(root, &["init", "-q", "--object-format=sha256"]);
        } else {
            run_test_git(root, &["init", "-q"]);
        }
        run_test_git(root, &["config", "user.email", "test@example.invalid"]);
        run_test_git(root, &["config", "user.name", "Test"]);
        std::fs::write(root.join("tracked.txt"), b"tracked\n").unwrap();
        run_test_git(root, &["add", "tracked.txt"]);
        run_test_git(root, &["commit", "-q", "-m", "initial"]);
        run_test_git(root, &["rev-parse", "HEAD"])
    }

