    #[cfg(unix)]
    #[test]
    fn passive_git_topology_accepts_standard_local_clones_with_linked_objects() {
        use std::os::unix::fs::MetadataExt as _;

        fn contains_linked_object(directory: &std::path::Path) -> bool {
            std::fs::read_dir(directory).unwrap().any(|entry| {
                let entry = entry.unwrap();
                let metadata = std::fs::symlink_metadata(entry.path()).unwrap();
                if metadata.file_type().is_dir() {
                    contains_linked_object(&entry.path())
                } else {
                    metadata.file_type().is_file() && metadata.nlink() > 1
                }
            })
        }

        for packed in [false, true] {
            let root = tempfile::tempdir().unwrap();
            let source = root.path().join("source");
            let clone = root.path().join("clone");
            std::fs::create_dir(&source).unwrap();
            init_test_git_repository(&source, false);
            if packed {
                run_test_git(&source, &["gc", "--prune=now"]);
            }
            run_test_git(
                root.path(),
                &[
                    "clone",
                    "-q",
                    source.to_str().unwrap(),
                    clone.to_str().unwrap(),
                ],
            );

            assert!(
                contains_linked_object(&clone.join(".git/objects")),
                "a standard same-filesystem local clone should exercise linked object payloads"
            );
            let clone_root = SecureDir::open(&clone).unwrap();
            let git = clone_root.existing_child(".git").unwrap();
            AxocoatlDaemon::validate_passive_git_write_topology(&git).unwrap();
        }
    }

    #[cfg(unix)]
    #[test]
    fn attempt_git_exclude_repairs_cross_uid_read_mode() {
        use std::os::unix::fs::PermissionsExt as _;

        let workspace = tempfile::tempdir().unwrap();
        // This test owns only the exclude-file contract. Keep its fixture free
        // of incidental object directories that Git may prune asynchronously.
        std::fs::create_dir_all(workspace.path().join(".git/info")).unwrap();
        let exclude = workspace.path().join(".git/info/exclude");
        std::fs::write(&exclude, ".axo-variants/\n").unwrap();
        std::fs::set_permissions(&exclude, std::fs::Permissions::from_mode(0o600)).unwrap();
        let workspace_root = SecureDir::open(workspace.path()).unwrap();
        let git = workspace_root.existing_child(".git").unwrap();

        AxocoatlDaemon::ensure_attempt_git_exclude(&git).unwrap();

        let mode = std::fs::metadata(&exclude).unwrap().permissions().mode() & 0o777;
        assert_eq!(mode, 0o644);
        assert!(std::fs::read_to_string(exclude)
            .unwrap()
            .lines()
            .any(|line| line == ".axo-variants/"));
    }

