    /// End-to-end regression for Podman Desktop's clone -> host atomic rename
    /// -> immediate Git-read visibility boundary. Run explicitly with Podman.
    #[cfg(unix)]
    #[tokio::test]
    #[ignore = "requires Podman; run this test explicitly"]
    async fn attempt_git_exclude_reaches_an_existing_podman_mount_before_checkout() {
        let workspace = tempfile::tempdir().unwrap();
        let workspace_path = std::fs::canonicalize(workspace.path()).unwrap();
        init_test_git_repository(&workspace_path, false);
        let sandbox_id = format!("git-visibility-test-{}", uuid::Uuid::new_v4());
        let sandbox = Arc::new(
            SessionSandbox::start(
                &sandbox_id,
                &workspace_path,
                None,
                &[],
                &[],
                &axocoatl_isolation::session_sandbox::SandboxPolicy::default(),
            )
            .await
            .unwrap(),
        );
        let sandbox_trait: Arc<dyn Sandbox> = sandbox.clone();
        let outcome = async {
            let root = workspace_path.to_string_lossy().to_string();
            let lane = workspace_path.join("podman-visibility-lane");
            let lane_string = lane.to_string_lossy().to_string();
            let clone = sandbox_trait
                .exec(
                    &[
                        "git",
                        "clone",
                        "-q",
                        "--no-hardlinks",
                        "--dissociate",
                        "--no-checkout",
                        &root,
                        &lane_string,
                    ],
                    Duration::from_secs(120),
                )
                .await
                .map_err(|error| error.to_string())?;
            if !clone.ok() {
                return Err(format!("container clone failed: {}", clone.stderr.trim()));
            }
            let lane_root = SecureDir::open(&lane).map_err(|error| error.to_string())?;
            let git = lane_root
                .existing_child(".git")
                .map_err(|error| error.to_string())?;
            AxocoatlDaemon::ensure_attempt_git_exclude(&git).map_err(|error| error.to_string())?;
            AxocoatlDaemon::wait_for_attempt_git_exclude_visibility(
                &sandbox_trait,
                &lane_string,
                "waiting for the test lane exclude file",
            )
            .await
            .map_err(|error| error.to_string())?;
            let checkout = AxocoatlDaemon::session_git_in_sandbox(
                &sandbox_trait,
                &lane_string,
                &["checkout", "-q", "HEAD"],
            )
            .await
            .map_err(|error| error.to_string())?;
            if !checkout.ok() {
                return Err(format!(
                    "container checkout failed: {}",
                    checkout.stderr.trim()
                ));
            }
            Ok::<(), String>(())
        }
        .await;
        let cleanup = sandbox.stop_checked().await;
        assert!(cleanup.is_ok(), "Podman cleanup failed: {cleanup:?}");
        outcome.unwrap();
    }

