        for name in ["commit-graph", "packs"] {
            let index = workspace.path().join(".git/objects/info").join(name);
            std::fs::write(&index, format!("recognized {name}\n")).unwrap();
            std::fs::hard_link(&index, outside.path().join(name)).unwrap();
        }
        let workspace_root = SecureDir::open(workspace.path()).unwrap();
        let git = workspace_root.existing_child(".git").unwrap();
