    #[tokio::test]
    async fn normal_session_fallback_route_is_reachable_and_pinned_after_restart() {
        let config = fallback_test_config();
        let primary_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let fallback_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let fallback_models = Arc::new(StdMutex::new(Vec::new()));
        let mut registry = ProviderRegistry::new();
        registry.register(Arc::new(FallbackRouteProbe {
            id: "openai",
            model: "primary-model",
            rate_limited: true,
            calls: primary_calls.clone(),
            model_overrides: Arc::new(StdMutex::new(Vec::new())),
        }));
        registry.register(Arc::new(FallbackRouteProbe {
            id: "anthropic",
            model: "fallback-default",
            rate_limited: false,
            calls: fallback_calls.clone(),
            model_overrides: fallback_models.clone(),
        }));

        let provider = AxocoatlDaemon::resolve_agent_provider(
            &config,
            &registry,
            "openai",
            Some("primary-model"),
        )
        .unwrap();
        let mut first_request = axocoatl_llm::ChatRequest::simple("inspect the file");
        first_request.model_override = Some("primary-model".to_string());
        let first = provider.chat(first_request).await.unwrap();
        assert_eq!(first.tool_calls.len(), 1);
        let tool_call = first.tool_calls[0].clone();
        assert_eq!(
            tool_call
                .provider_metadata
                .get(axocoatl_llm::TOOL_METADATA_ROUTE_PROVIDER)
                .map(String::as_str),
            Some("anthropic"),
        );
        assert_eq!(
            tool_call
                .provider_metadata
                .get(axocoatl_llm::TOOL_METADATA_ROUTE_MODEL)
                .map(String::as_str),
            Some("fallback-model"),
        );

        // Recreate the wrapper as a Session actor restart would. The retained
        // native transaction must route directly back to the same fallback;
        // it must not probe the rate-limited primary again.
        let restarted = AxocoatlDaemon::resolve_agent_provider(
            &config,
            &registry,
            "openai",
            Some("primary-model"),
        )
        .unwrap();
        let mut next_request = axocoatl_llm::ChatRequest::simple("unused");
        next_request.model_override = Some("primary-model".to_string());
        next_request.messages = vec![
            axocoatl_core::ChatMessage::user("inspect the file"),
            axocoatl_core::ChatMessage::assistant_with_tool_calls("", vec![tool_call]),
            axocoatl_core::ChatMessage::tool_result(
                r#"{"content":"source"}"#,
                "read_file",
                "fallback-call",
            ),
            axocoatl_core::ChatMessage::user("continue"),
        ];
        let next = restarted.chat(next_request).await.unwrap();
        assert_eq!(next.content, "fallback route stayed pinned");
        assert_eq!(primary_calls.load(std::sync::atomic::Ordering::SeqCst), 1,);
        assert_eq!(fallback_calls.load(std::sync::atomic::Ordering::SeqCst), 2,);
        assert_eq!(
            fallback_models.lock().unwrap().as_slice(),
            &[
                Some("fallback-model".to_string()),
                Some("fallback-model".to_string())
            ],
        );
    }

    #[tokio::test]
    async fn primary_only_agent_route_is_evidence_pinned_across_restart() {
        let config = primary_only_route_test_config();
        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let models = Arc::new(StdMutex::new(Vec::new()));
        let mut registry = ProviderRegistry::new();
        registry.register(Arc::new(FallbackRouteProbe {
            id: "openai",
            model: "model-a",
            rate_limited: false,
            calls: calls.clone(),
            model_overrides: models.clone(),
        }));

        let first =
            AxocoatlDaemon::resolve_agent_provider(&config, &registry, "openai", Some("model-a"))
                .unwrap();
        let mut first_request = axocoatl_llm::ChatRequest::simple("inspect the file");
        first_request.model_override = Some("model-a".to_string());
        let first_response = first.chat(first_request).await.unwrap();
        let tool_call = first_response.tool_calls.into_iter().next().unwrap();
        assert_eq!(
            tool_call
                .provider_metadata
                .get(axocoatl_llm::TOOL_METADATA_ROUTE_PROVIDER)
                .map(String::as_str),
            Some("openai")
        );
        assert_eq!(
            tool_call
                .provider_metadata
                .get(axocoatl_llm::TOOL_METADATA_ROUTE_MODEL)
                .map(String::as_str),
            Some("model-a")
        );

        let retained = vec![
            axocoatl_core::ChatMessage::user("inspect the file"),
            axocoatl_core::ChatMessage::assistant_with_tool_calls("", vec![tool_call]),
            axocoatl_core::ChatMessage::tool_result(
                r#"{"content":"source"}"#,
                "read_file",
                "fallback-call",
            ),
            axocoatl_core::ChatMessage::user("continue"),
        ];
        let encoded = serde_json::to_vec(&retained).unwrap();
        let restored = serde_json::from_slice::<Vec<axocoatl_core::ChatMessage>>(&encoded).unwrap();

        let switched =
            AxocoatlDaemon::resolve_agent_provider(&config, &registry, "openai", Some("model-b"))
                .unwrap();
        let mut switched_request = axocoatl_llm::ChatRequest::simple("unused");
        switched_request.messages = restored.clone();
        switched_request.model_override = Some("model-b".to_string());
        assert!(matches!(
            switched.chat(switched_request).await,
            Err(axocoatl_llm::ProviderError::InvalidRequest { message, .. })
                if message.contains("no longer matches")
        ));
        assert_eq!(
            calls.load(std::sync::atomic::Ordering::SeqCst),
            1,
            "model B must be rejected before provider dispatch"
        );

        let restarted =
            AxocoatlDaemon::resolve_agent_provider(&config, &registry, "openai", Some("model-a"))
                .unwrap();
        let mut same_route_request = axocoatl_llm::ChatRequest::simple("unused");
        same_route_request.messages = restored;
        same_route_request.model_override = Some("model-a".to_string());
        assert_eq!(
            restarted.chat(same_route_request).await.unwrap().content,
            "fallback route stayed pinned"
        );
        assert_eq!(calls.load(std::sync::atomic::Ordering::SeqCst), 2);
        assert_eq!(
            models.lock().unwrap().as_slice(),
            &[Some("model-a".to_string()), Some("model-a".to_string())]
        );
    }

