    #[tokio::test]
    async fn real_v0_1_4_checkpoint_imports_once_survives_restart_and_promotes_cache() {
        let data = tempfile::tempdir().unwrap();
        let work = tempfile::tempdir().unwrap();
        let session = legacy_migration_session("legacy-session", work.path());
        let checkpoint_root = data.path().join("checkpoints");
        let checkpoint_dir = checkpoint_root.join("legacy-session:coder");
        tokio::fs::create_dir_all(&checkpoint_dir).await.unwrap();
        let legacy =
            hex::decode(include_str!("../tests/fixtures/checkpoint-v0.1.4.hex").trim()).unwrap();
        let corrupt = b"newer-but-corrupt".to_vec();
        let legacy_path = checkpoint_dir.join("0000000000000012.ckpt");
        let corrupt_path = checkpoint_dir.join("0000000000000013.ckpt");
        tokio::fs::write(&legacy_path, &legacy).await.unwrap();
        tokio::fs::write(&corrupt_path, &corrupt).await.unwrap();

        let checkpoint_store = CheckpointStore::new(&checkpoint_root, CheckpointPolicy::Manual);
        let history_dir = data.path().join("session-history");
        let turn_store = tokio::sync::Mutex::new(SessionTurnStore::open(&history_dir).unwrap());

        // A process may stop after decode but before the first durable write.
        // Decode must leave both legacy candidates untouched, and the next
        // process can still perform the canonical import.
        let decoded = checkpoint_store
            .load_latest_with_encoding(&AgentId::new("legacy-session:coder"))
            .await
            .unwrap()
            .unwrap();
        assert_eq!(decoded.checkpoint.version, 12);
        assert_eq!(decoded.highest_seen_version, 13);
        assert!(decoded.encoding.is_legacy());
        assert!(turn_store.lock().await.is_empty());
        assert_eq!(tokio::fs::read(&legacy_path).await.unwrap(), legacy);
        assert_eq!(tokio::fs::read(&corrupt_path).await.unwrap(), corrupt);

        AxocoatlDaemon::migrate_session_turns_from_checkpoint(
            &session,
            &ApproximateCounter::new().unwrap(),
            &checkpoint_store,
            &turn_store,
            true,
        )
        .await
        .unwrap();

        let turns = turn_store.lock().await.list("legacy-session");
        assert_eq!(turns.len(), 1);
        assert_eq!(turns[0].user_input, "Please inspect src/lib.rs");
        assert_eq!(turns[0].final_output.as_deref(), Some("The answer is 42."));
        assert_eq!(turns[0].status, SessionTurnLifecycle::Completed);
        assert_eq!(turns[0].created_at, 1_710_000_001_000);
        assert_eq!(turns[0].updated_at, 1_710_000_004_000);
        assert_eq!(
            turns[0].metadata["checkpoint_encoding"],
            serde_json::json!("bincode_v0.1.1-v0.1.4")
        );

        let promoted_path = axocoatl_memory::storage_path(&checkpoint_root, "legacy-session:coder")
            .join("0000000000000014.ckpt");
        let promoted = tokio::fs::read(&promoted_path).await.unwrap();
        assert!(promoted.starts_with(b"AXOCKPT\0\x03"));
        assert_eq!(tokio::fs::read(&legacy_path).await.unwrap(), legacy);
        assert_eq!(tokio::fs::read(&corrupt_path).await.unwrap(), corrupt);

        let ledger_path = history_dir.join("turns.v1.jsonl");
        let ledger_before_restart = tokio::fs::read(&ledger_path).await.unwrap();
        drop(turn_store);

        let restarted_turn_store =
            tokio::sync::Mutex::new(SessionTurnStore::open(&history_dir).unwrap());
        let restarted_checkpoint_store =
            CheckpointStore::new(&checkpoint_root, CheckpointPolicy::Manual);
        AxocoatlDaemon::migrate_session_turns_from_checkpoint(
            &session,
            &ApproximateCounter::new().unwrap(),
            &restarted_checkpoint_store,
            &restarted_turn_store,
            true,
        )
        .await
        .unwrap();
        assert_eq!(
            restarted_turn_store.lock().await.list("legacy-session"),
            turns
        );
        assert_eq!(
            tokio::fs::read(&ledger_path).await.unwrap(),
            ledger_before_restart
        );
        let loaded = restarted_checkpoint_store
            .load_latest_with_encoding(&AgentId::new("legacy-session:coder"))
            .await
            .unwrap()
            .unwrap();
        assert_eq!(loaded.checkpoint.version, 14);
        assert_eq!(tokio::fs::read(&legacy_path).await.unwrap(), legacy);
        assert_eq!(tokio::fs::read(&corrupt_path).await.unwrap(), corrupt);
        assert_eq!(tokio::fs::read(&promoted_path).await.unwrap(), promoted);
        assert_eq!(
            loaded.encoding,
            axocoatl_memory::CheckpointEncoding::PostcardV1
        );
        assert!(!loaded.checkpoint.cumulative_token_usage_known);
        assert_eq!(loaded.checkpoint.session_messages.len(), 2);
        assert_eq!(
            loaded.checkpoint.session_messages[0].content,
            "Please inspect src/lib.rs"
        );
        assert_eq!(
            loaded.checkpoint.session_messages[1].content,
            "The answer is 42."
        );
        assert!(loaded
            .checkpoint
            .session_messages
            .iter()
            .all(|message| message.tool_calls.is_empty()
                && message.role != axocoatl_core::MessageRole::Tool));
    }

    #[tokio::test]
    async fn unframed_postcard_tool_request_without_final_answer_imports_interrupted_partial() {
        let data = tempfile::tempdir().unwrap();
        let work = tempfile::tempdir().unwrap();
        let session = legacy_migration_session("interrupted-session", work.path());
        let checkpoint_root = data.path().join("checkpoints");
        let checkpoint_dir =
            axocoatl_memory::storage_path(&checkpoint_root, "interrupted-session:coder");
        tokio::fs::create_dir_all(&checkpoint_dir).await.unwrap();
        let checkpoint = axocoatl_memory::AgentCheckpoint {
            version: 3,
            agent_id: "interrupted-session:coder".to_string(),
            checkpoint_time: 1_720_000_102,
            session_messages: vec![
                axocoatl_memory::StoredMessage {
                    content_parts: None,
                    role: axocoatl_core::MessageRole::User,
                    content: "Inspect the file".to_string(),
                    timestamp: 1_720_000_100,
                    token_count: 3,
                    name: None,
                    tool_calls: Vec::new(),
                    tool_call_id: None,
                },
                axocoatl_memory::StoredMessage {
                    content_parts: None,
                    role: axocoatl_core::MessageRole::Assistant,
                    content: "I started checking the file.".to_string(),
                    timestamp: 1_720_000_101,
                    token_count: 5,
                    name: None,
                    tool_calls: vec![axocoatl_memory::StoredToolCall {
                        id: "call-read".to_string(),
                        name: "read_file".to_string(),
                        arguments_json: r#"{"path":"src/lib.rs"}"#.to_string(),
                        provider_metadata: Default::default(),
                    }],
                    tool_call_id: None,
                },
            ],
            cumulative_token_usage: axocoatl_core::TokenUsageStats::new(8, 5),
            cumulative_token_usage_known: true,
            behavior_state: None,
        };
        let checkpoint_store = CheckpointStore::new(&checkpoint_root, CheckpointPolicy::Manual);
        checkpoint_store.save(&checkpoint).await.unwrap();
        let checkpoint_path = checkpoint_dir.join("0000000000000003.ckpt");
        let enveloped = tokio::fs::read(&checkpoint_path).await.unwrap();
        assert!(enveloped.starts_with(b"AXOCKPT\0\x03"));
        let unframed = enveloped[9..].to_vec();
        tokio::fs::write(&checkpoint_path, &unframed).await.unwrap();
        let original = checkpoint_store
            .load_latest_with_encoding(&AgentId::new("interrupted-session:coder"))
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            original.encoding,
            axocoatl_memory::CheckpointEncoding::UnframedPostcard
        );
        assert_eq!(
            serde_json::to_value(&original.checkpoint).unwrap(),
            serde_json::to_value(&checkpoint).unwrap()
        );
        assert_eq!(
            original.checkpoint.session_messages[1].tool_calls[0].id,
            "call-read"
        );

        let turn_store = tokio::sync::Mutex::new(
            SessionTurnStore::open(data.path().join("session-history")).unwrap(),
        );
        AxocoatlDaemon::migrate_session_turns_from_checkpoint(
            &session,
            &ApproximateCounter::new().unwrap(),
            &checkpoint_store,
            &turn_store,
            true,
        )
        .await
        .unwrap();

        let turns = turn_store.lock().await.list("interrupted-session");
        assert_eq!(tokio::fs::read(&checkpoint_path).await.unwrap(), unframed);
        assert_eq!(turns.len(), 1);
        assert_eq!(turns[0].status, SessionTurnLifecycle::Interrupted);
        assert_eq!(turns[0].partial_output, "I started checking the file.");
        assert!(turns[0].final_output.is_none());
        assert!(turns[0]
            .error
            .as_deref()
            .is_some_and(|error| error.contains("before an assistant response")));
        assert_eq!(
            turns[0].metadata["checkpoint_encoding"],
            serde_json::json!("postcard_unframed_launch_candidate")
        );
        assert!(
            tokio::fs::read(checkpoint_dir.join("0000000000000004.ckpt"))
                .await
                .unwrap()
                .starts_with(b"AXOCKPT\0\x03")
        );
        let promoted = checkpoint_store
            .load_latest_with_encoding(&AgentId::new("interrupted-session:coder"))
            .await
            .unwrap()
            .unwrap();
        assert!(promoted.checkpoint.cumulative_token_usage_known);
        assert_eq!(promoted.checkpoint.session_messages.len(), 2);
        assert_eq!(
            promoted.checkpoint.session_messages[0].content,
            "Inspect the file"
        );
        assert_eq!(
            promoted.checkpoint.session_messages[1].content,
            "I started checking the file."
        );
        assert!(promoted
            .checkpoint
            .session_messages
            .iter()
            .all(|message| message.tool_calls.is_empty()
                && message.role != axocoatl_core::MessageRole::Tool));
    }

    #[test]
    fn legacy_path_session_creation_registers_and_reuses_durable_workspace() {
        let data = tempfile::tempdir().unwrap();
        let project = tempfile::tempdir().unwrap();
        let mut workspaces = WorkspaceStore::new(data.path().join("workspaces")).unwrap();
        let mut sessions = SessionStore::new(data.path().join("sessions")).unwrap();

        let first = AxocoatlDaemon::create_legacy_session_in_stores(
            &mut workspaces,
            &mut sessions,
            "First Session",
            project.path().to_str().unwrap(),
            SessionMode::SingleAgent {
                agent_id: "coder".to_string(),
            },
            Vec::new(),
            vec![3000],
            None,
        )
        .unwrap();
        assert_eq!(workspaces.len(), 1);
        assert!(!first.workspace_id.is_empty());
        AxocoatlDaemon::require_session_preview_port(&first, 3000)
            .expect("configured logical container ports are valid Preview targets");
        assert!(AxocoatlDaemon::require_session_preview_port(&first, 43210).is_err());
        workspaces
            .rename(&first.workspace_id, "Custom project name")
            .unwrap();

        let second = AxocoatlDaemon::create_legacy_session_in_stores(
            &mut workspaces,
            &mut sessions,
            "Second Session",
            project.path().to_str().unwrap(),
            SessionMode::SingleAgent {
                agent_id: "coder".to_string(),
            },
            Vec::new(),
            Vec::new(),
            None,
        )
        .unwrap();

        assert_eq!(first.workspace_id, second.workspace_id);
        assert_eq!(workspaces.len(), 1);
        assert_eq!(
            workspaces.get(&first.workspace_id).unwrap().name,
            "Custom project name",
            "legacy create omits a Workspace name and must not overwrite a custom label"
        );
        sessions.close(&first.id).unwrap();
        sessions.close(&second.id).unwrap();
        assert_eq!(workspaces.list().len(), 1);
        assert_eq!(
            sessions.list_for_workspace(&first.workspace_id).len(),
            2,
            "closed Sessions remain linked and the Workspace remains independently visible"
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn bootstrap_fails_with_missing_provider() {
        use std::os::unix::fs::PermissionsExt;

        const CHILD: &str = "AXOCOATL_TEST_MISSING_PROVIDER_CHILD";
        if std::env::var_os(CHILD).is_some() {
            let result = AxocoatlDaemon::bootstrap(test_config()).await;
            let err = result.unwrap_err().to_string();
            assert!(
                err.contains("mock"),
                "Error should mention mock provider: {err}"
            );
            return;
        }

        // Bootstrap reads its data root and invokes Podman through the process
        // environment. Isolate those inputs in a child, without changing the
        // parallel test process or skipping real early runtime reconciliation.
        let root = tempfile::tempdir().unwrap();
        let bin = root.path().join("bin");
        std::fs::create_dir(&bin).unwrap();
        let podman = bin.join("podman");
        std::fs::write(
            &podman,
            r#"#!/bin/sh
printf '%s\n' "$*" >> "$AXOCOATL_TEST_PODMAN_CALLS"
case "$*" in
  --version) printf 'podman version 5.0.0\n' ;;
  'machine list --format json') printf '[{"Running":true}]\n' ;;
  'info --format json') printf '{}\n' ;;
  'ps -a --no-trunc --filter name=axo-ses- --format '* | \
  'ps -a --no-trunc --filter name=axo-ses- --filter name=axo-egr- --filter name=axo-brw- --filter name=axo-pvw- --filter name=axo-svc- --filter label=io.axocoatl.runtime-authority='*) ;;
  *) printf 'unexpected Podman command: %s\n' "$*" >&2; exit 1 ;;
esac
"#,
        )
        .unwrap();
        std::fs::set_permissions(&podman, std::fs::Permissions::from_mode(0o700)).unwrap();
        let calls_path = root.path().join("podman-calls");
        let output = tokio::time::timeout(
            Duration::from_secs(60),
            tokio::process::Command::new(std::env::current_exe().unwrap())
                .args([
                    "--exact",
                    "bootstrap::tests::bootstrap_fails_with_missing_provider",
                    "--nocapture",
                ])
                .current_dir(root.path())
                .env(CHILD, "1")
                .env("AXOCOATL_DATA_DIR", root.path().join("data"))
                .env("AXOCOATL_SOCKET_PATH", root.path().join("ipc/daemon.sock"))
                .env("AXOCOATL_TEST_PODMAN_CALLS", &calls_path)
                .env("PATH", &bin)
                .kill_on_drop(true)
                .output(),
        )
        .await
        .expect("isolated bootstrap test timed out")
        .expect("starting isolated bootstrap test");
        assert!(
            output.status.success(),
            "isolated bootstrap test failed:\n{}\n{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        let calls = std::fs::read_to_string(calls_path).unwrap();
        assert_eq!(
            calls.lines().filter(|line| line.starts_with("ps ")).count(),
            4,
            "early bootstrap must inspect all three protected roots and owned containers: {calls}"
        );
        assert_eq!(
            calls
                .lines()
                .filter(|line| line.contains("label=io.axocoatl.runtime-authority="))
                .count(),
            1,
            "early bootstrap must inspect exact authority-owned containers: {calls}"
        );
    }

    #[tokio::test]
    async fn early_bootstrap_reconciles_runtime_creation_before_later_failure() {
        let data = tempfile::tempdir().unwrap();
        let work = tempfile::tempdir().unwrap();
        let mut sessions = SessionStore::new(data.path().join("sessions")).unwrap();
        let session = sessions
            .create_with_environment(
                "Interrupted create",
                "wsp-interrupted-create",
                work.path(),
                SessionMode::SingleAgent {
                    agent_id: "test-agent".into(),
                },
                Vec::new(),
                Vec::new(),
                None,
                None,
                false,
                true,
            )
            .unwrap();
        let preparing = sessions
            .set_environment(
                &session.id,
                SessionEnvironmentState::Preparing,
                Some("e2b:base".into()),
                None,
                Vec::new(),
                None,
            )
            .unwrap();
        let creation_token = test_e2b_ownership_token(&preparing);
        let (api_url, mut requests, server) = start_fake_e2b_control_plane(vec![
            test_e2b_owned_list("committed-before-restart", &creation_token),
            test_e2b_owned_sandbox("committed-before-restart", &creation_token),
            test_http_response("204 No Content", ""),
        ])
        .await;
        let config = e2b_test_config(&api_url);
        sessions
            .set_runtime_creation_if_preparing(
                &session.id,
                preparing.environment.generation,
                SessionRuntimeCreationAttempt {
                    backend: "e2b".into(),
                    token: creation_token.clone(),
                    remote_root: "/home/user/repository".into(),
                    control_plane: api_url.clone(),
                    data_plane_domain: "sandbox.test".into(),
                    authority_fingerprint: AxocoatlDaemon::e2b_authority_fingerprint("test-key"),
                    discovered_ids: Vec::new(),
                },
            )
            .unwrap();
        let session_id = session.id;
        drop(sessions);

        let result = async {
            AxocoatlDaemon::reconcile_persisted_session_records(
                &config,
                &SecureDir::open(data.path()).unwrap(),
            )
            .await?;
            Err::<(), DaemonError>(DaemonError::Provider(
                "injected later bootstrap failure".into(),
            ))
        }
        .await;
        assert!(result
            .unwrap_err()
            .to_string()
            .contains("injected later bootstrap failure"));
        let list = requests.recv().await.expect("metadata LIST request");
        assert!(list.starts_with("GET /v2/sandboxes?"));
        assert!(list.contains("metadata=axocoatl_creation_token%3D"));
        let proof = requests.recv().await.expect("exact ownership GET");
        assert!(proof.starts_with("GET /sandboxes/committed-before-restart HTTP/1.1"));
        let delete = requests.recv().await.expect("exact DELETE request");
        assert!(delete.starts_with("DELETE /sandboxes/committed-before-restart HTTP/1.1"));
        server.await.unwrap();

        let mut reopened = SessionStore::new(data.path().join("sessions")).unwrap();
        reopened.load_all().unwrap();
        let session = reopened.get(&session_id).unwrap();
        assert!(session.environment.runtime_creation.is_none());
        assert!(session.environment.runtime.is_none());
    }

