    #[tokio::test]
    async fn copied_e2b_id_and_token_cannot_authorize_another_session() {
        let (api_url, mut requests, server) =
            start_fake_e2b_control_plane(vec![test_http_response(
                "500 Internal Error",
                "unexpected provider request",
            )])
            .await;
        let config = e2b_test_config(&api_url);
        let data = tempfile::tempdir().unwrap();
        let work_a = tempfile::tempdir().unwrap();
        let work_b = tempfile::tempdir().unwrap();
        let mut sessions = SessionStore::new(data.path().join("sessions")).unwrap();
        let session_a = sessions
            .create_with_environment(
                "Owner A",
                "wsp-owner-a",
                work_a.path(),
                SessionMode::SingleAgent {
                    agent_id: "test-agent".into(),
                },
                Vec::new(),
                Vec::new(),
                None,
                None,
                false,
                true,
            )
            .unwrap();
        let session_b = sessions
            .create_with_environment(
                "Forged B",
                "wsp-owner-b",
                work_b.path(),
                SessionMode::SingleAgent {
                    agent_id: "test-agent".into(),
                },
                Vec::new(),
                Vec::new(),
                None,
                None,
                false,
                true,
            )
            .unwrap();
        let copied = SessionRuntimeIdentity {
            backend: "e2b".into(),
            id: "owner-a-runtime".into(),
            remote_root: Some("/home/user/repository".into()),
            control_plane: Some(api_url),
            data_plane_domain: Some("sandbox.test".into()),
            authority_fingerprint: Some(AxocoatlDaemon::e2b_authority_fingerprint("test-key")),
            ownership_token: Some(test_e2b_ownership_token(&session_a)),
            cleanup_confirmed: false,
        };
        let mut owner_record = copied.clone();
        owner_record.cleanup_confirmed = true;
        sessions
            .set_environment(
                &session_a.id,
                SessionEnvironmentState::Ready,
                Some("e2b:base".into()),
                Some(owner_record),
                Vec::new(),
                None,
            )
            .unwrap();
        sessions
            .set_environment(
                &session_b.id,
                SessionEnvironmentState::Ready,
                Some("e2b:base".into()),
                Some(copied),
                Vec::new(),
                None,
            )
            .unwrap();
        drop(sessions);

        AxocoatlDaemon::reconcile_persisted_session_records(
            &config,
            &SecureDir::open(data.path()).unwrap(),
        )
        .await
        .unwrap();
        assert!(
            tokio::time::timeout(Duration::from_millis(100), requests.recv())
                .await
                .is_err(),
            "copying Session A's id and token into B must issue zero provider requests"
        );
        server.abort();

        let mut reopened = SessionStore::new(data.path().join("sessions")).unwrap();
        reopened.load_all().unwrap();
        let forged = reopened.get(&session_b.id).unwrap();
        assert!(forged
            .environment
            .error
            .as_deref()
            .is_some_and(|error| error.contains("not bound to Session")));
    }

