    async fn early_pause_failure_keeps_ready_identity_and_never_deletes() {
        let (api_url, mut requests, server) = start_fake_e2b_control_plane(vec![
            test_e2b_owned_list("ready-pause-retry-id", TEST_E2B_REQUEST_TOKEN),
            test_e2b_owned_sandbox("ready-pause-retry-id", TEST_E2B_REQUEST_TOKEN),
            test_http_response("503 Service Unavailable", "pause unavailable"),
            test_http_response("204 No Content", ""),
        ])
        .await;
        let config = e2b_test_config(&api_url);
        let data = tempfile::tempdir().unwrap();
        let work = tempfile::tempdir().unwrap();
        let session_id = {
            let mut sessions = SessionStore::new(data.path().join("sessions")).unwrap();
            let session = sessions
                .create_with_environment(
                    "Ready pause retry",
                    "wsp-ready-pause-retry",
                    work.path(),
                    SessionMode::SingleAgent {
                        agent_id: "test-agent".into(),
                    },
                    Vec::new(),
                    Vec::new(),
                    None,
                    None,
                    false,
                    true,
                )
                .unwrap();
            sessions
                .set_environment(
                    &session.id,
                    SessionEnvironmentState::Ready,
                    Some("e2b:base".into()),
                    Some(SessionRuntimeIdentity {
                        backend: "e2b".into(),
                        id: "ready-pause-retry-id".into(),
                        remote_root: Some("/home/user/repository".into()),
                        control_plane: Some(api_url),
                        data_plane_domain: Some("sandbox.test".into()),
                        authority_fingerprint: Some(AxocoatlDaemon::e2b_authority_fingerprint(
                            "test-key",
                        )),
                        ownership_token: Some(test_e2b_ownership_token(&session)),
                        cleanup_confirmed: false,
                    }),
                    Vec::new(),
                    None,
                )
                .unwrap();
            session.id
        };

        AxocoatlDaemon::reconcile_persisted_session_records(
            &config,
            &SecureDir::open(data.path()).unwrap(),
        )
        .await
        .expect("pause transport failure stays actionable without aborting startup");
        let list = requests.recv().await.expect("pause ownership LIST");
        assert!(list.starts_with("GET /v2/sandboxes?"));
        let proof = requests.recv().await.expect("pause ownership GET");
        assert!(proof.starts_with("GET /sandboxes/ready-pause-retry-id HTTP/1.1"));
        let pause = requests.recv().await.expect("attempted PAUSE request");
        assert!(pause.starts_with("POST /sandboxes/ready-pause-retry-id/pause HTTP/1.1"));
        assert!(
            tokio::time::timeout(Duration::from_millis(100), requests.recv())
                .await
                .is_err(),
            "a failed soft PAUSE must never become DELETE"
        );
        server.abort();
        let mut reopened = SessionStore::new(data.path().join("sessions")).unwrap();
        reopened.load_all().unwrap();
        let session = reopened.get(&session_id).unwrap();
        assert_eq!(session.environment.state, SessionEnvironmentState::Ready);
        let runtime = session
            .environment
            .runtime
            .as_ref()
            .expect("exact identity retained");
        assert_eq!(runtime.id, "ready-pause-retry-id");
        assert!(!runtime.cleanup_confirmed);
        assert!(session
            .environment
            .error
            .as_deref()
            .is_some_and(|error| error.contains("pause unavailable")));
    }

    #[test]
    fn cleanup_interrupts_running_lanes_and_checks_but_never_keep() {
        use crate::git::AttemptSetState;

        assert!(AxocoatlDaemon::attempt_state_is_interruptible(
            AttemptSetState::Running
        ));
        assert!(AxocoatlDaemon::attempt_state_is_interruptible(
            AttemptSetState::Checking
        ));
        assert!(AxocoatlDaemon::attempt_is_interrupt_target(
            Some("set-current"),
            "set-current",
            AttemptSetState::Running
        ));
        assert!(
            !AxocoatlDaemon::attempt_is_interrupt_target(
                Some("set-stale"),
                "set-current",
                AttemptSetState::Running
            ),
            "a stale Discard must never interrupt the current set"
        );
        for state in [
            AttemptSetState::Preparing,
            AttemptSetState::Ready,
            AttemptSetState::Verified,
            AttemptSetState::Judged,
            AttemptSetState::Failed,
            AttemptSetState::Discarding,
            AttemptSetState::Applying,
            AttemptSetState::Applied,
            AttemptSetState::TranscriptRecorded,
        ] {
            assert!(
                !AxocoatlDaemon::attempt_state_is_interruptible(state),
                "state {state:?} must not be interrupted out of band"
            );
        }
    }

    #[test]
    fn attempt_results_keep_owned_preparation_live_and_mark_orphans_interrupted() {
        use crate::git::{AttemptLaneState, AttemptSetState};

        let live = AxocoatlDaemon::observed_attempt_lane_state(0, None, true);
        assert_eq!(live.state, AttemptLaneState::Queued);
        assert!(live.error.is_none());
        assert_eq!(
            AxocoatlDaemon::observed_attempt_set_state(
                AttemptSetState::Preparing,
                true,
                std::slice::from_ref(&live),
                &[],
                None,
            ),
            AttemptSetState::Preparing,
            "the operation owner covers the pre-active-runtime launch window"
        );
        assert_eq!(
            AxocoatlDaemon::observed_attempt_set_state(
                AttemptSetState::Running,
                true,
                std::slice::from_ref(&live),
                &[],
                None,
            ),
            AttemptSetState::Running,
        );

        let interrupted = AxocoatlDaemon::observed_attempt_lane_state(0, None, false);
        assert_eq!(interrupted.state, AttemptLaneState::Interrupted);
        assert!(interrupted
            .error
            .as_deref()
            .is_some_and(|error| error.contains("interrupted")));
        assert!(interrupted.finished_at.is_some());
        assert_eq!(
            AxocoatlDaemon::observed_attempt_set_state(
                AttemptSetState::Preparing,
                false,
                &[interrupted],
                &[],
                None,
            ),
            AttemptSetState::Failed,
            "a Preparing record without a process owner is restart/cancellation recovery"
        );
    }

