    async fn wait_until_stream_gate_is_owned(gate: &tokio::sync::Mutex<()>) {
        for _ in 0..100 {
            if gate.try_lock().is_err() {
                return;
            }
            tokio::task::yield_now().await;
        }
        panic!("stream lifecycle commit did not acquire its gate");
    }

    #[tokio::test]
    async fn reconnect_cut_cannot_hide_a_newly_owned_session_turn() {
        let gate = Arc::new(tokio::sync::Mutex::new(()));
        let active = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
        let bus = crate::stream::StreamBus::new(16);
        let mut subscriber = bus.subscribe();

        // Freeze the ownership registry after the lifecycle commit obtains
        // the outer gate. A pre-fix snapshot could inspect the empty registry,
        // then include Accepted/Start in its cursor and lose the live turn.
        let active_guard = active.lock().await;
        let start_gate = gate.clone();
        let start_active = active.clone();
        let start_bus = bus.clone();
        let start = tokio::spawn(async move {
            commit_session_start(
                &start_gate,
                &start_active,
                &start_bus,
                "session-b",
                "turn-b",
                AgentRunControl::new(AgentRunId::new("turn-b")),
            )
            .await;
        });
        wait_until_stream_gate_is_owned(&gate).await;
        let cut_gate = gate.clone();
        let cut_active = active.clone();
        let cut_bus = bus.clone();
        let cut = tokio::spawn(async move {
            live_run_snapshot_cut(&cut_gate, &cut_active, &cut_bus, None).await
        });

        drop(active_guard);
        start.await.unwrap();
        let (cursor, snapshot, environment_transitions, attempt_ownerships) = cut.await.unwrap();
        assert!(environment_transitions.is_empty());
        assert!(attempt_ownerships.is_empty());
        assert_eq!(cursor, 2);
        assert_eq!(snapshot.len(), 1);
        assert_eq!(snapshot[0].workflow, "session-b");
        assert_eq!(snapshot[0].turn_id.as_deref(), Some("turn-b"));

        for expected_sequence in 1..=2 {
            let envelope = subscriber.recv_sequenced().await.unwrap();
            assert_eq!(envelope.sequence, expected_sequence);
            assert!(envelope.sequence <= cursor);
        }
    }

    #[tokio::test]
    async fn terminal_ledger_observation_reattaches_while_cleanup_owner_is_live() {
        let history = tempfile::tempdir().unwrap();
        let mut ledger = SessionTurnStore::open(history.path()).unwrap();
        ledger
            .begin(BeginSessionTurn {
                turn_id: Some("turn-cleanup".to_string()),
                session_id: "session-cleanup".to_string(),
                user_input: "finish".to_string(),
                agent_id: Some("lead".to_string()),
                model: None,
                context: Vec::new(),
                idempotency_key: Some("turn-cleanup".to_string()),
                metadata: serde_json::Map::new(),
            })
            .unwrap();
        ledger
            .transition(
                "turn-cleanup",
                "terminal-before-cache-cleanup",
                TransitionSessionTurn {
                    status: SessionTurnLifecycle::Completed,
                    final_output: Some("done".to_string()),
                    error: None,
                    metadata: serde_json::Map::new(),
                },
            )
            .unwrap();
        assert_eq!(
            ledger.get("turn-cleanup").unwrap().status,
            SessionTurnLifecycle::Completed
        );

        let gate = tokio::sync::Mutex::new(());
        let active = tokio::sync::Mutex::new(HashMap::new());
        let bus = crate::stream::StreamBus::new(16);
        commit_session_start(
            &gate,
            &active,
            &bus,
            "session-cleanup",
            "turn-cleanup",
            AgentRunControl::new(AgentRunId::new("turn-cleanup")),
        )
        .await;

        let retry = if replay_session_start(&gate, &active, &bus, "session-cleanup", "turn-cleanup")
            .await
        {
            Err(DaemonError::SessionTurnReattached {
                session: "session-cleanup".to_string(),
                turn: "turn-cleanup".to_string(),
            })
        } else {
            AxocoatlDaemon::outcome_from_terminal_turn(ledger.get("turn-cleanup").unwrap())
        };
        assert!(
            matches!(
                retry,
                Err(DaemonError::SessionTurnReattached { session, turn })
                    if session == "session-cleanup" && turn == "turn-cleanup"
            ),
            "the retry must reattach instead of returning the terminal outcome while cleanup owns the turn"
        );
        assert_eq!(
            active
                .lock()
                .await
                .get("session-cleanup")
                .map(|turn| turn.turn_id.as_str()),
            Some("turn-cleanup")
        );
    }

    #[tokio::test]
    async fn reconnect_cut_cannot_resurrect_a_terminal_session_turn() {
        let gate = Arc::new(tokio::sync::Mutex::new(()));
        let active = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
        let bus = crate::stream::StreamBus::new(16);
        let mut subscriber = bus.subscribe();
        commit_session_start(
            &gate,
            &active,
            &bus,
            "session-a",
            "turn-a",
            AgentRunControl::new(AgentRunId::new("turn-a")),
        )
        .await;

        // Freeze the ownership registry after terminal commit obtains the
        // outer gate. A pre-fix snapshot could retain this stale active row,
        // include the terminal sequence in its cursor, then expose a ghost
        // Stop control forever.
        let active_guard = active.lock().await;
        let terminal_gate = gate.clone();
        let terminal_active = active.clone();
        let terminal_bus = bus.clone();
        let terminal = tokio::spawn(async move {
            commit_session_terminal(
                &terminal_gate,
                &terminal_active,
                &terminal_bus,
                "session-a",
                "turn-a",
                crate::stream::StreamFrame::SessionDone {
                    session: "session-a".to_string(),
                    turn_id: Some("turn-a".to_string()),
                    input_tokens: 3,
                    output_tokens: 5,
                    reasoning_tokens: 0,
                    token_usage_known: true,
                },
            )
            .await;
        });
        wait_until_stream_gate_is_owned(&gate).await;
        let cut_gate = gate.clone();
        let cut_active = active.clone();
        let cut_bus = bus.clone();
        let cut = tokio::spawn(async move {
            live_run_snapshot_cut(&cut_gate, &cut_active, &cut_bus, None).await
        });

        drop(active_guard);
        terminal.await.unwrap();
        let (cursor, snapshot, environment_transitions, attempt_ownerships) = cut.await.unwrap();
        assert!(environment_transitions.is_empty());
        assert!(attempt_ownerships.is_empty());
        assert_eq!(cursor, 3);
        assert!(snapshot.iter().all(|run| run.workflow != "session-a"));
        assert!(!active.lock().await.contains_key("session-a"));

        for expected_sequence in 1..=3 {
            let envelope = subscriber.recv_sequenced().await.unwrap();
            assert_eq!(envelope.sequence, expected_sequence);
            assert!(envelope.sequence <= cursor);
        }
    }

