    #[tokio::test]
    async fn terminal_route_releases_operation_before_removing_live_owner() {
        let gate = tokio::sync::Mutex::new(());
        let active = tokio::sync::Mutex::new(HashMap::new());
        let operation = tokio::sync::Mutex::new(());
        let bus = crate::stream::StreamBus::new(16);
        let mut subscriber = bus.subscribe();
        commit_session_start(
            &gate,
            &active,
            &bus,
            "session-terminal-barrier",
            "turn-terminal-barrier",
            AgentRunControl::new(AgentRunId::new("turn-terminal-barrier")),
        )
        .await;

        let operation_guard = operation.lock().await;
        let publication_barrier = gate.lock().await;
        let terminal = commit_session_terminal_after_operation_release(
            operation_guard,
            &gate,
            &active,
            &bus,
            "session-terminal-barrier",
            "turn-terminal-barrier",
            crate::stream::StreamFrame::SessionDone {
                session: "session-terminal-barrier".to_string(),
                turn_id: Some("turn-terminal-barrier".to_string()),
                input_tokens: 3,
                output_tokens: 5,
                reasoning_tokens: 0,
                token_usage_known: true,
            },
        );
        tokio::pin!(terminal);
        tokio::select! {
            _ = &mut terminal => panic!("terminal publication crossed a deliberately held barrier"),
            _ = async {
                for _ in 0..100 {
                    if operation.try_lock().is_ok() {
                        return;
                    }
                    tokio::task::yield_now().await;
                }
                panic!("terminal route did not release its operation lease before publication");
            } => {}
        }

        assert_eq!(
            active
                .lock()
                .await
                .get("session-terminal-barrier")
                .map(|turn| turn.turn_id.as_str()),
            Some("turn-terminal-barrier"),
            "an exact retry must still see the live owner while terminal publication is blocked"
        );
        assert_eq!(subscriber.recv_sequenced().await.unwrap().sequence, 1);
        assert_eq!(subscriber.recv_sequenced().await.unwrap().sequence, 2);
        assert!(matches!(
            subscriber.try_recv(),
            Err(tokio::sync::broadcast::error::TryRecvError::Empty)
        ));

        drop(publication_barrier);
        terminal.await;
        let terminal = subscriber.recv_sequenced().await.unwrap();
        assert_eq!(terminal.sequence, 3);
        assert!(matches!(
            terminal.frame,
            crate::stream::StreamFrame::SessionDone {
                ref session,
                turn_id: Some(ref turn_id),
                ..
            } if session == "session-terminal-barrier" && turn_id == "turn-terminal-barrier"
        ));
        assert!(!active.lock().await.contains_key("session-terminal-barrier"));
    }

    #[tokio::test]
    async fn preflight_error_does_not_release_another_turns_live_ownership() {
        let gate = tokio::sync::Mutex::new(());
        let active = tokio::sync::Mutex::new(HashMap::new());
        let bus = crate::stream::StreamBus::new(16);
        let mut subscriber = bus.subscribe();
        commit_session_start(
            &gate,
            &active,
            &bus,
            "session-a",
            "turn-a",
            AgentRunControl::new(AgentRunId::new("turn-a")),
        )
        .await;

        commit_session_preflight_error(
            &gate,
            &active,
            &bus,
            "session-a",
            "turn-b",
            &DaemonError::SessionConflict("turn-a is already running".to_string()),
        )
        .await;

        assert_eq!(active.lock().await["session-a"].turn_id, "turn-a");
        assert_eq!(
            bus.run("session-a").and_then(|run| run.turn_id),
            Some("turn-a".to_string())
        );
        assert_eq!(subscriber.recv_sequenced().await.unwrap().sequence, 1);
        assert_eq!(subscriber.recv_sequenced().await.unwrap().sequence, 2);
        let error = subscriber.recv_sequenced().await.unwrap();
        assert_eq!(error.sequence, 3);
        assert!(matches!(
            error.frame,
            crate::stream::StreamFrame::SessionError {
                ref session,
                turn_id: Some(ref turn_id),
                ..
            } if session == "session-a" && turn_id == "turn-b"
        ));
    }

    #[tokio::test]
    async fn conflicting_same_turn_preflight_cannot_terminalize_the_live_executor() {
        let gate = tokio::sync::Mutex::new(());
        let active = tokio::sync::Mutex::new(HashMap::new());
        let bus = crate::stream::StreamBus::new(16);
        let mut subscriber = bus.subscribe();
        let control = AgentRunControl::new(AgentRunId::new("turn-live"));
        commit_session_start(
            &gate,
            &active,
            &bus,
            "session-live",
            "turn-live",
            control.clone(),
        )
        .await;

        commit_session_preflight_error(
            &gate,
            &active,
            &bus,
            "session-live",
            "turn-live",
            &DaemonError::Session(
                "turn 'turn-live' already exists with different request data".to_string(),
            ),
        )
        .await;

        assert_eq!(subscriber.recv_sequenced().await.unwrap().sequence, 1);
        assert_eq!(subscriber.recv_sequenced().await.unwrap().sequence, 2);
        let rejected = subscriber.recv_sequenced().await.unwrap();
        assert_eq!(rejected.sequence, 3);
        assert!(matches!(
            rejected.frame,
            crate::stream::StreamFrame::SessionRequestRejected {
                ref session,
                ref turn_id,
                ref error,
            } if session == "session-live"
                && turn_id == "turn-live"
                && error.contains("different request data")
        ));
        assert_eq!(
            active
                .lock()
                .await
                .get("session-live")
                .map(|turn| turn.turn_id.as_str()),
            Some("turn-live")
        );
        assert_eq!(
            bus.run("session-live").and_then(|run| run.turn_id),
            Some("turn-live".to_string()),
            "the live RunState and its exact Stop identity must remain visible"
        );

        bus.send(crate::stream::StreamFrame::Token {
            workflow: "session-live".to_string(),
            agent: "coder".to_string(),
            turn_id: Some("turn-live".to_string()),
            delta: "still running".to_string(),
        })
        .unwrap();
        assert_eq!(
            bus.run("session-live").unwrap().agents[0].output,
            "still running",
            "later output from the real executor must continue folding"
        );
        assert_eq!(
            request_active_session_turn_cancellation(&active, "session-live", Some("turn-live"))
                .await
                .unwrap(),
            Some(true),
            "the exact Stop handle must remain reachable"
        );
        assert!(control.is_cancelled());
        assert_eq!(subscriber.recv_sequenced().await.unwrap().sequence, 4);
    }

    #[tokio::test]
    async fn close_cancels_exact_active_turn_before_waiting_for_workspace_lease() {
        let active_turns = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
        let active_control = AgentRunControl::new(AgentRunId::new("turn-active"));
        let other_control = AgentRunControl::new(AgentRunId::new("turn-other"));
        active_turns.lock().await.insert(
            "session-active".to_string(),
            ActiveSessionTurn {
                turn_id: "turn-active".to_string(),
                control: active_control.clone(),
            },
        );
        active_turns.lock().await.insert(
            "session-other".to_string(),
            ActiveSessionTurn {
                turn_id: "turn-other".to_string(),
                control: other_control.clone(),
            },
        );

        let stale = request_active_session_turn_cancellation(
            &active_turns,
            "session-active",
            Some("turn-stale"),
        )
        .await;
        assert!(matches!(stale, Err(DaemonError::Session(_))));
        assert!(
            !active_control.is_cancelled(),
            "a stale exact Stop target must not cancel the current turn"
        );

        // Model the normal turn holding the per-Session operation lease while
        // Close starts. Close's cancellation phase must complete even though
        // its subsequent lease acquisition cannot.
        let operation = Arc::new(tokio::sync::Mutex::new(()));
        let turn_lease = operation.clone().lock_owned().await;
        let active_for_close = active_turns.clone();
        let operation_for_close = operation.clone();
        let close = tokio::spawn(async move {
            let requested =
                request_active_session_turn_cancellation(&active_for_close, "session-active", None)
                    .await?;
            let _cleanup_lease = operation_for_close.lock_owned().await;
            Ok::<_, DaemonError>(requested)
        });

        tokio::time::timeout(Duration::from_millis(250), active_control.cancelled())
            .await
            .expect("Close must request cancellation before waiting for the operation lease");
        assert!(
            !other_control.is_cancelled(),
            "Close must not cancel another Session's turn"
        );
        assert!(
            !close.is_finished(),
            "Close should still wait for the running turn to reach its safe boundary"
        );

        drop(turn_lease);
        assert_eq!(close.await.unwrap().unwrap(), Some(true));
    }

