    #[tokio::test]
    async fn checked_review_ignores_a_non_idempotent_setup_rerun() {
        use std::process::Command;

        fn direct_program(command: &[String]) -> Option<&str> {
            let first = command.first()?.as_str();
            if first != "env" {
                return Some(first);
            }
            let mut index = 1;
            while let Some(argument) = command.get(index) {
                if argument == "-u" {
                    command.get(index + 1)?;
                    index += 2;
                } else if argument.contains('=') {
                    index += 1;
                } else {
                    return Some(argument);
                }
            }
            None
        }

        let repo = tempfile::tempdir().unwrap();
        let git = |args: &[&str]| {
            let output = Command::new("git")
                .arg("-C")
                .arg(repo.path())
                .args(args)
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "git {args:?}: {}",
                String::from_utf8_lossy(&output.stderr)
            );
            output.stdout
        };
        git(&["init", "-q"]);
        git(&["config", "user.email", "agent@axocoatl.local"]);
        git(&["config", "user.name", "Axocoatl"]);
        std::fs::write(repo.path().join("candidate.txt"), "base\n").unwrap();
        // Model the approved setup having run once before the lane was judged.
        std::fs::write(repo.path().join("setup-artifact.txt"), "x\n").unwrap();
        git(&["add", "-A"]);
        git(&["commit", "-q", "-m", "base"]);
        let base_sha = String::from_utf8(git(&["rev-parse", "HEAD"]))
            .unwrap()
            .trim()
            .to_string();
        let base_tree = String::from_utf8(git(&["rev-parse", "HEAD^{tree}"]))
            .unwrap()
            .trim()
            .to_string();

        std::fs::write(repo.path().join("candidate.txt"), "checked\n").unwrap();
        git(&["add", "-A"]);
        git(&["commit", "-q", "-m", "checked candidate"]);
        let commit_oid = String::from_utf8(git(&["rev-parse", "HEAD"]))
            .unwrap()
            .trim()
            .to_string();
        let tree_oid = String::from_utf8(git(&["rev-parse", "HEAD^{tree}"]))
            .unwrap()
            .trim()
            .to_string();
        let set_id = "0190aabb-ccdd-7eef-8899-aabbccddeeff";
        let reference = crate::attempts::checked_candidate_ref(set_id, 0);
        git(&["update-ref", &reference, &commit_oid]);
        let patch = git(&[
            "-c",
            "diff.algorithm=myers",
            "diff",
            "--binary",
            "--full-index",
            "--no-ext-diff",
            "--no-textconv",
            "--no-renames",
            &base_sha,
            &reference,
        ]);

        let lane = crate::git::Variant {
            index: 0,
            branch: crate::attempts::branch_name(set_id, 0),
            worktree: repo.path().to_string_lossy().to_string(),
            model: Some("test-model".to_string()),
            agent: Some("test-agent".to_string()),
            provider: Some("test-provider".to_string()),
        };
        let set = crate::git::AttemptSet {
            id: set_id.to_string(),
            session_id: "session-checked-review".to_string(),
            task: "make the candidate better".to_string(),
            instruction: "make the candidate better".to_string(),
            base_sha: base_sha.clone(),
            base_tree,
            state: crate::git::AttemptSetState::Verified,
            kept_index: None,
            created_at: 1,
            lanes: vec![lane.clone()],
        };
        let checked = StoredCheckedTree {
            index: 0,
            commit_oid,
            tree_oid,
            patch_sha256: AxocoatlDaemon::bytes_sha256(&patch),
            changes_gitlink: false,
        };

        assert_eq!(
            AxocoatlDaemon::attempt_review_source(crate::git::AttemptSetState::Ready),
            AttemptReviewSource::LiveWorktree,
            "pre-Checks Compare must remain live"
        );
        assert_eq!(
            AxocoatlDaemon::attempt_review_source(crate::git::AttemptSetState::Verified),
            AttemptReviewSource::CheckedCandidate
        );
        assert_eq!(
            AxocoatlDaemon::attempt_review_source(crate::git::AttemptSetState::Judged),
            AttemptReviewSource::CheckedCandidate
        );

        // This is the old failure mode: recreating an unowned lane would run
        // the approved setup a second time and mutate its worktree after Checks.
        std::fs::write(repo.path().join("setup-artifact.txt"), "x\nx\n").unwrap();
        let live_status = String::from_utf8(git(&["status", "--porcelain=v1"])).unwrap();
        assert!(live_status.contains("setup-artifact.txt"));

        let local = LocalGitSandbox::new(repo.path());
        let sandbox: Arc<dyn Sandbox> = Arc::new(local.clone());
        let validated_reference = AxocoatlDaemon::validate_checked_candidate_reference_in_sandbox(
            &sandbox, &set, &checked,
        )
        .await
        .unwrap();
        assert_eq!(validated_reference, reference);
        let status = AxocoatlDaemon::checked_variant_status_in_sandbox(
            &sandbox,
            &set,
            &lane,
            &validated_reference,
        )
        .await
        .unwrap();
        assert_eq!(
            status
                .status
                .files
                .iter()
                .map(|file| file.path.as_str())
                .collect::<Vec<_>>(),
            vec!["candidate.txt"],
            "post-Checks status must exclude the setup rerun"
        );
        let candidate_diff = AxocoatlDaemon::git_diff_between_references_in_sandbox(
            &sandbox,
            repo.path().to_str().unwrap(),
            &base_sha,
            &validated_reference,
            "candidate.txt",
        )
        .await
        .unwrap();
        assert_eq!(candidate_diff.old, "base\n");
        assert_eq!(candidate_diff.new, "checked\n");
        let setup_diff = AxocoatlDaemon::git_diff_between_references_in_sandbox(
            &sandbox,
            repo.path().to_str().unwrap(),
            &base_sha,
            &validated_reference,
            "setup-artifact.txt",
        )
        .await
        .unwrap();
        assert_eq!(setup_diff.old, "x\n");
        assert_eq!(setup_diff.new, "x\n");
        assert_eq!(
            String::from_utf8(git(&[
                "show",
                &format!("{}:candidate.txt", checked.commit_oid)
            ]))
            .unwrap(),
            candidate_diff.new,
            "Compare, Judge, and Keep must consume the same protected checked tree"
        );
        assert!(
            local
                .commands()
                .iter()
                .all(|command| direct_program(command) == Some("git")),
            "post-Checks status/diff must not invoke a setup shell"
        );
    }

    #[tokio::test]
    async fn interrupted_cleanup_wait_acquires_a_released_workspace_lease() {
        let operation = Arc::new(tokio::sync::Mutex::new(()));
        let holder = operation.clone().lock_owned().await;
        let waiter = Box::pin(operation.lock_owned());
        let release = tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(10)).await;
            drop(holder);
        });

        let guard = AxocoatlDaemon::wait_for_attempt_operation_after_interrupt(
            waiter,
            Duration::from_millis(250),
        )
        .await;
        assert!(guard.is_ok(), "cleanup must acquire the released lease");
        release.await.unwrap();
    }

    #[tokio::test]
    async fn interrupted_cleanup_wait_is_bounded_when_a_lease_will_not_release() {
        let operation = Arc::new(tokio::sync::Mutex::new(()));
        let _holder = operation.clone().lock_owned().await;
        let waiter = Box::pin(operation.lock_owned());
        let started = std::time::Instant::now();

        let result = AxocoatlDaemon::wait_for_attempt_operation_after_interrupt(
            waiter,
            Duration::from_millis(20),
        )
        .await;
        assert!(matches!(result, Err(DaemonError::AttemptConflict(_))));
        assert!(
            started.elapsed() < Duration::from_millis(250),
            "cleanup must return a retryable conflict instead of hanging"
        );
    }

    #[test]
    fn only_loopback_ollama_endpoints_have_a_known_zero_model_api_cost() {
        for endpoint in [
            "http://localhost:11434",
            "https://LOCALHOST./v1",
            "http://worker.localhost:11434",
            "http://127.0.0.1:11434",
            "http://127.42.0.9:11434",
            "http://[::1]:11434",
        ] {
            assert!(
                AxocoatlDaemon::endpoint_is_loopback(endpoint),
                "expected loopback endpoint: {endpoint}"
            );
        }

        for endpoint in [
            "http://ollama.example.com",
            "https://192.0.2.10:11434",
            "http://0.0.0.0:11434",
            "unix:///tmp/ollama.sock",
            "not a URL",
        ] {
            assert!(
                !AxocoatlDaemon::endpoint_is_loopback(endpoint),
                "expected remote or invalid endpoint: {endpoint}"
            );
        }
    }

    #[test]
    fn baseline_cost_requires_every_lanes_real_token_volume() {
        let known = crate::git::LaneUsage {
            index: 0,
            model: Some("remote-model".to_string()),
            input_tokens: 100,
            output_tokens: 20,
            reasoning_tokens: 7,
            token_usage_known: true,
            cost_usd: 0.001,
            cost_known: true,
            duration_ms: 10,
        };
        let unknown = crate::git::LaneUsage {
            index: 1,
            model: Some("remote-model".to_string()),
            input_tokens: 0,
            output_tokens: 0,
            reasoning_tokens: 0,
            token_usage_known: false,
            cost_usd: 0.0,
            cost_known: false,
            duration_ms: 10,
        };

        assert!(AxocoatlDaemon::complete_lane_token_volume(
            std::slice::from_ref(&known),
            1
        ));
        assert!(!AxocoatlDaemon::complete_lane_token_volume(
            std::slice::from_ref(&known),
            2
        ));
        assert!(!AxocoatlDaemon::complete_lane_token_volume(
            &[known, unknown],
            2
        ));
    }

