    #[cfg(unix)]
    #[tokio::test]
    async fn keep_fingerprints_preserve_raw_bytes_and_never_follow_parent_symlinks() {
        use std::os::unix::fs::{symlink, PermissionsExt};

        let workspace = tempfile::tempdir().unwrap();
        let outside = tempfile::tempdir().unwrap();
        tokio::fs::write(outside.path().join("child"), b"outside-secret")
            .await
            .unwrap();
        symlink(outside.path(), workspace.path().join("link")).unwrap();
        let workspace_dir = SecureDir::open(workspace.path()).unwrap();
        let affected = HashSet::from(["link".to_string(), "link/child".to_string()]);
        assert_eq!(
            AxocoatlDaemon::fingerprint_keep_workspace_path(
                &workspace_dir,
                std::path::Path::new("link/child"),
                &affected,
            )
            .unwrap(),
            None,
            "an affected parent symlink makes its descendant logically absent"
        );

        let raw_path = workspace.path().join("raw");
        tokio::fs::write(&raw_path, [0xff, b'\n']).await.unwrap();
        let mut permissions = tokio::fs::metadata(&raw_path).await.unwrap().permissions();
        permissions.set_mode(0o755);
        tokio::fs::set_permissions(&raw_path, permissions)
            .await
            .unwrap();
        let fingerprint = AxocoatlDaemon::fingerprint_keep_workspace_path(
            &workspace_dir,
            std::path::Path::new("raw"),
            &HashSet::new(),
        )
        .unwrap()
        .unwrap();
        assert_eq!(fingerprint.kind, "file");
        assert_eq!(
            fingerprint.sha256,
            AxocoatlDaemon::bytes_sha256(&[0xff, b'\n'])
        );
        assert!(fingerprint.executable);
    }

    #[cfg(unix)]
    #[test]
    fn keep_checkout_forces_symlink_semantics() {
        use std::os::unix::fs::symlink;
        use std::process::Command;

        let repo = tempfile::tempdir().unwrap();
        let run = |args: &[&str]| {
            Command::new("git")
                .arg("-C")
                .arg(repo.path())
                .args(args)
                .output()
                .unwrap()
        };
        assert!(run(&["init", "-q"]).status.success());
        std::fs::write(repo.path().join("target"), b"target").unwrap();
        symlink("target", repo.path().join("link")).unwrap();
        assert!(run(&["add", "target", "link"]).status.success());
        let tree = String::from_utf8(run(&["write-tree"]).stdout).unwrap();
        assert!(run(&["config", "core.symlinks", "false"]).status.success());

        let stage = tempfile::tempdir().unwrap();
        let index = repo.path().join("keep.index");
        let git_dir = repo.path().join(".git");
        let read_tree = Command::new("git")
            .env("GIT_INDEX_FILE", &index)
            .arg("-C")
            .arg(repo.path())
            .args(["read-tree", tree.trim()])
            .output()
            .unwrap();
        assert!(read_tree.status.success());
        let checkout = Command::new("git")
            .env("GIT_DIR", &git_dir)
            .env("GIT_INDEX_FILE", &index)
            .env("GIT_WORK_TREE", stage.path())
            .args([
                "-c",
                "core.filemode=true",
                "-c",
                "core.symlinks=true",
                "checkout-index",
                "--force",
                "--all",
            ])
            .output()
            .unwrap();
        assert!(checkout.status.success());
        assert!(std::fs::symlink_metadata(stage.path().join("link"))
            .unwrap()
            .file_type()
            .is_symlink());
    }

    #[test]
    fn checked_patch_hash_is_streamed_and_bounded_for_dense_and_sparse_files() {
        let root = tempfile::tempdir().unwrap();
        let store = SecureDir::open(root.path()).unwrap();
        std::fs::write(root.path().join("patch"), [0xff, 0x00, b'\n']).unwrap();
        assert_eq!(
            AxocoatlDaemon::secure_file_sha256_limited(&store, std::path::Path::new("patch"), 3,)
                .unwrap(),
            AxocoatlDaemon::bytes_sha256(&[0xff, 0x00, b'\n'])
        );
        assert!(AxocoatlDaemon::secure_file_sha256_limited(
            &store,
            std::path::Path::new("patch"),
            2,
        )
        .is_err());

        let sparse = std::fs::File::create(root.path().join("sparse-patch")).unwrap();
        sparse.set_len(ATTEMPT_PATCH_CAP as u64 + 1).unwrap();
        assert!(AxocoatlDaemon::secure_file_sha256_limited(
            &store,
            std::path::Path::new("sparse-patch"),
            ATTEMPT_PATCH_CAP,
        )
        .is_err());
    }

